func:
// ======================================================
// WATTPILOT – Befehle (On Message)
//
// Eingang des Subflows:
//
//   msg.topic = "wattpilot/set"
//   msg.payload = { key: "amp", value: 16 }
//                 oder [ { key, value }, ... ]
//                 oder { amp: 16, frc: 2 }
//
//   msg.topic = "gui/wattpilot"      (Dashboard-Buttons)
//   msg.payload = { key, value }     nur erlaubte Schlüssel
//
//   msg.topic = "wattpilot/reconnect"
//   msg.topic = "wattpilot/get"      -> aktuelle Daten ausgeben
//
// Alles andere wird ignoriert.
// ======================================================

const api = context.get("api");

if (!api) {
    node.status({ fill: "red", shape: "ring", text: "nicht gestartet" });
    return null;
}

// Erlaubte Werte für Befehle aus dem Dashboard
const GUI_RULES = {
    lmo: v => [3, 4, 5].includes(v),                 // Standard / Eco / Next Trip
    frc: v => [0, 1, 2].includes(v),                 // Neutral / Aus / Ein
    amp: v => Number.isInteger(v) && v >= 6 && v <= 32,
    psm: v => [0, 1, 2].includes(v),                 // Auto / 1-phasig / 3-phasig
    fup: v => v === true || v === false              // PV-Überschuss
};

function toList(payload) {
    if (Array.isArray(payload)) return payload;
    if (payload && typeof payload === "object") {
        if (typeof payload.key === "string") return [payload];
        return Object.entries(payload).map(([key, value]) => ({ key, value }));
    }
    return [];
}

function sendList(list, rules) {
    const sent = [];

    for (const cmd of list) {
        if (!cmd || typeof cmd.key !== "string" || cmd.value === undefined) continue;

        let value = cmd.value;
        if (rules) {
            const check = rules[cmd.key];
            if (typeof value === "string" && value.trim() !== "" && !isNaN(value)) {
                value = Number(value);
            }
            if (!check || !check(value)) {
                node.warn("Wattpilot: Befehl nicht erlaubt: " + JSON.stringify(cmd));
                continue;
            }
        }

        if (api.sendSet(cmd.key, value)) {
            sent.push({ key: cmd.key, value });
        }
    }

    return sent;
}

switch (msg.topic) {

    case "wattpilot/set":
    case "gui/wattpilot": {
        if (!api.isConnected()) {
            node.warn("Wattpilot nicht verbunden, Befehl verworfen");
            return [null, { topic: "wattpilot_event", event: "notConnected", payload: msg.payload }, null];
        }
        const rules = msg.topic === "gui/wattpilot" ? GUI_RULES : null;
        const sent = sendList(toList(msg.payload), rules);
        return [null, { topic: "wattpilot_event", event: "commandSent", payload: sent }, null];
    }

    case "wattpilot/reconnect":
        api.reconnect();
        return null;

    case "wattpilot/get":
        return [{ topic: "wattpilot_data", payload: api.data() }, null, null];

    default:
        return null;
}

initialize:
// ======================================================
// WATTPILOT – Verbindung (On Start)
//
// Einstellungen kommen aus dem Subflow-Node "Wattpilot":
//   WATTPILOT_IP        IP-Adresse der Wallbox
//   WATTPILOT_PASSWORD  Passwort aus der Wattpilot-App (Credential,
//                       wird NICHT in flows.json gespeichert)
//   WATTPILOT_UPDATE_MS wie oft Daten ausgegeben werden (ms)
//
// Ausgänge des Subflows:
//   1) aufbereitete Daten (msg.topic = "wattpilot_data")
//   2) Ereignisse (Anmeldung, Befehlsantworten, Fehler)
//   3) Status des Subflow-Nodes
// ======================================================

const IP = String(env.get("WATTPILOT_IP") || "").trim();
const PASSWORD = String(env.get("WATTPILOT_PASSWORD") || "");
const UPDATE_MS = Math.max(250, Number(env.get("WATTPILOT_UPDATE_MS")) || 1000);

const RECONNECT_MS = 15000;   // Wartezeit vor neuem Verbindungsversuch
const PING_MS = 30000;        // Lebenszeichen an die Wallbox
const WATCHDOG_MS = 90000;    // ohne Nachricht -> neu verbinden

// ------------------------------------------------------
// Laufzeit-Zustand (nur im Speicher)
// ------------------------------------------------------

const st = {
    ws: null,
    stopped: false,
    reconnectTimer: null,
    pingTimer: null,
    publishTimer: null,
    lastMessage: 0,
    lastPublish: 0,
    raw: {},
    hashCache: {},
    conn: {
        serial: null,
        devicetype: null,
        version: null,
        secured: true,
        authenticated: false,
        hashedPassword: null,
        requestId: 0,
        lastError: null
    }
};

// ------------------------------------------------------
// Ausgänge
// ------------------------------------------------------

function out(data, event, status) {
    node.send([data || null, event || null, status || null]);
}

function setStatus(fill, text) {
    const s = { fill, shape: fill === "green" || fill === "blue" ? "dot" : "ring", text };
    node.status(s);
    out(null, null, { payload: s });
}

function event(type, payload) {
    out(null, { topic: "wattpilot_event", event: type, payload }, null);
}

// ------------------------------------------------------
// Anmeldung
// ------------------------------------------------------

function sha256hex(text) {
    return crypto.createHash("sha256").update(text, "utf8").digest("hex");
}

function bcryptSaltFromSerial(serial) {
    // 16 Byte, Ziffern der Seriennummer rechtsbündig als Rohwerte 0-9
    const b = new Array(16).fill(0);
    const s = String(serial);
    const offset = 16 - s.length;
    for (let i = 0; i < s.length; i++) {
        if (offset + i >= 0) b[offset + i] = s.charCodeAt(i) - 48;
    }
    return bcrypt.encodeBase64(b, 16);
}

function hashPassword(serial, password, algorithm) {
    if (algorithm === "bcrypt") {
        if (!/^\d+$/.test(String(serial))) {
            throw new Error("Seriennummer muss nur aus Ziffern bestehen");
        }
        const salt = "$2a$08$" + bcryptSaltFromSerial(serial);
        return bcrypt.hashSync(sha256hex(password), salt).substring(salt.length);
    }

    // pbkdf2 (Wattpilot Home)
    return crypto
        .pbkdf2Sync(password, String(serial), 100000, 256, "sha512")
        .toString("base64")
        .substring(0, 32);
}

// ------------------------------------------------------
// Senden
// ------------------------------------------------------

function sendJson(obj) {
    if (st.ws && st.ws.readyState === 1) {
        st.ws.send(JSON.stringify(obj));
        return true;
    }
    return false;
}

function sendSet(key, value) {
    const c = st.conn;
    if (!c.authenticated) return false;

    // Feldreihenfolge wie bei der Referenz-Implementierung
    const setValue = { requestId: c.requestId, key, value, type: "setValue" };
    let wsMsg = setValue;

    if (c.secured) {
        const data = JSON.stringify(setValue);
        const hmac = crypto
            .createHmac("sha256", Buffer.from(c.hashedPassword, "utf8"))
            .update(data, "utf8")
            .digest("hex");
        wsMsg = { type: "securedMsg", data, requestId: c.requestId + "sm", hmac };
    }

    // requestId startet pro Verbindung bei 0 und steigt um 1
    c.requestId++;
    return sendJson(wsMsg);
}

// ------------------------------------------------------
// Daten aufbereiten
// ------------------------------------------------------

function num(v) {
    if (v === null || v === undefined || v === "") return null;
    const n = Number(v);
    return Number.isFinite(n) ? n : null;
}

function round(v, d = 0) {
    const n = num(v);
    if (n === null) return null;
    const f = Math.pow(10, d);
    return Math.round(n * f) / f;
}

const CAR_STATES = { 0: "Unbekannt", 1: "Kein Auto", 2: "Lädt", 3: "Wartet", 4: "Ladung beendet", 5: "Fehler" };
const MODES = { 3: "Standard", 4: "Eco", 5: "Next Trip" };
const FORCE = { 0: "Neutral", 1: "Aus", 2: "Ein" };
const PHASE_MODE = { 0: "Auto", 1: "1-phasig", 2: "3-phasig" };

function buildData() {
    const raw = st.raw;
    const c = st.conn;
    const nrg = Array.isArray(raw.nrg) ? raw.nrg : [];

    const carState = num(raw.car);
    const mode = num(raw.lmo);
    const force = num(raw.frc);
    const psm = num(raw.psm);
    const wh = num(raw.wh);
    const eto = num(raw.eto);

    return {
        connected: c.authenticated === true,
        ip: IP,
        serial: c.serial || raw.sse || null,
        devicetype: c.devicetype || null,
        firmware: c.version || raw.fwv || null,
        last_error: c.lastError,

        // Fahrzeug
        car_state: carState,
        car_state_label: CAR_STATES[carState] ?? "—",
        car_connected: carState === 2 || carState === 3 || carState === 4,
        charging: carState === 2,
        charging_allowed: raw.alw === true,
        model_status: num(raw.modelStatus),
        error: num(raw.err),

        // Leistung / Energie
        // nrg: [U1, U2, U3, UN, I1, I2, I3, P1, P2, P3, PN, Pges, ...]
        power_w: round(nrg[11], 0),
        power_l1_w: round(nrg[7], 0),
        power_l2_w: round(nrg[8], 0),
        power_l3_w: round(nrg[9], 0),
        voltage_l1_v: round(nrg[0], 1),
        voltage_l2_v: round(nrg[1], 1),
        voltage_l3_v: round(nrg[2], 1),
        current_l1_a: round(nrg[4], 2),
        current_l2_a: round(nrg[5], 2),
        current_l3_a: round(nrg[6], 2),
        phases_active: num(raw.pnp),
        session_kwh: wh !== null ? round(wh / 1000, 2) : null,
        total_kwh: eto !== null ? round(eto / 1000, 1) : null,

        // Einstellungen
        current_a: num(raw.amp),
        current_max_a: num(raw.ama),
        current_min_a: num(raw.mca),
        cable_limit_a: num(raw.cbl),
        mode,
        mode_label: MODES[mode] ?? "—",
        force_state: force,
        force_state_label: FORCE[force] ?? "—",
        phase_mode: psm,
        phase_mode_label: PHASE_MODE[psm] ?? "—",
        pv_surplus_enabled: raw.fup === true,
        pv_start_power_w: num(raw.fst),
        pv_battery_limit_soc: num(raw.fam),
        boost_enabled: raw.ebe === true,
        boost_battery_soc: num(raw.ebt),
        zero_feedin: raw.fzf === true,

        // Was der Wattpilot selbst vom Wechselrichter sieht
        wp_grid_w: num(raw.pgrid),
        wp_pv_w: num(raw.ppv),
        wp_battery_w: num(raw.pakku),
        wp_avg_grid_w: num(raw.pvopt_averagePGrid),
        wp_avg_pv_w: num(raw.pvopt_averagePPv),
        wp_avg_battery_w: num(raw.pvopt_averagePAkku),

        updated_at: new Date().toISOString()
    };
}

function publish(force) {
    const now = Date.now();
    const wait = UPDATE_MS - (now - st.lastPublish);

    if (!force && wait > 0) {
        if (!st.publishTimer) {
            st.publishTimer = setTimeout(() => {
                st.publishTimer = null;
                publish(true);
            }, wait);
        }
        return;
    }

    st.lastPublish = now;
    const data = buildData();

    // Für andere Flows (z. B. Strategie) global ablegen
    global.set("wattpilot", data);
    global.set("wattpilot_raw", st.raw);

    if (data.connected) {
        setStatus(
            data.charging ? "blue" : "green",
            data.car_state_label + " | " + (data.power_w ?? 0) + " W | " +
            data.mode_label + " | " + (data.current_a ?? "—") + " A"
        );
    }

    out({ topic: "wattpilot_data", payload: data }, null, null);
}

// ------------------------------------------------------
// Nachrichten vom Wattpilot
// ------------------------------------------------------

function onMessage(text) {
    st.lastMessage = Date.now();

    let m;
    try {
        m = JSON.parse(text);
    } catch (e) {
        return;
    }
    if (!m || typeof m !== "object") return;

    const c = st.conn;

    switch (m.type) {
        case "hello":
            Object.assign(c, {
                serial: m.serial,
                devicetype: m.devicetype,
                version: m.version,
                secured: m.secured !== false,
                authenticated: m.secured === false,
                hashedPassword: null,
                requestId: 0
            });
            setStatus("yellow", "verbunden, Anmeldung …");
            event("hello", m);
            break;

        case "authRequired": {
            if (!PASSWORD) {
                c.lastError = "Kein Passwort eingestellt";
                setStatus("red", "Passwort fehlt (Node-Einstellungen)");
                return;
            }
            const algorithm = m.hash || (c.devicetype === "wattpilot_flex" ? "bcrypt" : "pbkdf2");
            const key = c.serial + "|" + algorithm;
            try {
                if (!st.hashCache[key]) {
                    st.hashCache = { [key]: hashPassword(c.serial, PASSWORD, algorithm) };
                }
            } catch (e) {
                c.lastError = "Hash-Fehler: " + e.message;
                setStatus("red", "Hash-Fehler");
                return;
            }
            c.hashedPassword = st.hashCache[key];

            const token3 = crypto.randomBytes(16).toString("hex");
            const hash1 = sha256hex(m.token1 + c.hashedPassword);
            sendJson({ type: "auth", token3, hash: sha256hex(token3 + m.token2 + hash1) });
            break;
        }

        case "authSuccess":
            c.authenticated = true;
            c.requestId = 0;
            c.lastError = null;
            event("authSuccess", { serial: c.serial });
            setStatus("green", "angemeldet " + c.serial + ", lade Daten …");
            break;

        case "authError":
            c.authenticated = false;
            c.lastError = "Anmeldung fehlgeschlagen: " + (m.message || "");
            setStatus("red", "Passwort falsch");
            event("authError", m);
            // Nicht im Sekundentakt falsche Passwörter senden
            closeSocket();
            scheduleReconnect(RECONNECT_MS * 4);
            break;

        case "fullStatus":
        case "deltaStatus":
            Object.assign(st.raw, m.status || {});
            publish(m.type === "fullStatus" && m.partial === false);
            break;

        case "response":
            if (m.success === false) {
                event("commandRejected", m);
                node.warn("Wattpilot hat Befehl abgelehnt: " + (m.message || JSON.stringify(m)));
            } else {
                if (m.status && typeof m.status === "object") {
                    Object.assign(st.raw, m.status);
                    publish(true);
                }
                event("commandOk", m);
            }
            break;

        default:
            break;
    }
}

// ------------------------------------------------------
// Verbindung
// ------------------------------------------------------

function closeSocket() {
    clearInterval(st.pingTimer);
    st.pingTimer = null;
    const ws = st.ws;
    st.ws = null;
    if (ws) {
        ws.removeAllListeners();
        ws.on("error", () => {});
        try { ws.terminate(); } catch (e) { }
    }
    st.conn.authenticated = false;
}

function scheduleReconnect(delay) {
    if (st.stopped || st.reconnectTimer) return;
    st.reconnectTimer = setTimeout(() => {
        st.reconnectTimer = null;
        connect();
    }, delay ?? RECONNECT_MS);
}

function connect() {
    if (st.stopped) return;
    closeSocket();

    if (!IP) {
        setStatus("red", "IP-Adresse fehlt (Node-Einstellungen)");
        return;
    }

    setStatus("yellow", "verbinde " + IP + " …");

    let ws;
    try {
        ws = new WebSocket("ws://" + IP + "/ws", { handshakeTimeout: 10000 });
    } catch (e) {
        st.conn.lastError = e.message;
        setStatus("red", "Fehler: " + e.message);
        scheduleReconnect();
        return;
    }

    st.ws = ws;
    st.lastMessage = Date.now();

    ws.on("message", data => onMessage(data.toString()));
    ws.on("pong", () => { st.lastMessage = Date.now(); });

    ws.on("error", err => {
        st.conn.lastError = err.message;
        setStatus("red", "Fehler: " + err.message);
    });

    ws.on("close", () => {
        if (st.ws !== ws) return;
        st.conn.authenticated = false;
        if (!st.stopped) {
            setStatus("red", "getrennt, neuer Versuch in " + RECONNECT_MS / 1000 + " s");
            publish(true);
            scheduleReconnect();
        }
    });

    st.pingTimer = setInterval(() => {
        if (st.ws !== ws) return;
        if (Date.now() - st.lastMessage > WATCHDOG_MS) {
            setStatus("red", "keine Antwort, verbinde neu");
            closeSocket();
            scheduleReconnect(1000);
            return;
        }
        try { ws.ping(); } catch (e) { }
    }, PING_MS);
}

// ------------------------------------------------------
// Schnittstelle für "On Message" und "On Stop"
// ------------------------------------------------------

context.set("api", {
    sendSet,
    reconnect: () => { st.conn.lastError = null; connect(); },
    isConnected: () => st.conn.authenticated === true,
    data: () => buildData(),
    stop: () => {
        st.stopped = true;
        clearTimeout(st.reconnectTimer);
        clearTimeout(st.publishTimer);
        closeSocket();
    }
});

connect();

finalize:
// WATTPILOT – Verbindung sauber beenden (On Stop / Deploy)
const api = context.get("api");
if (api) api.stop();
context.set("api", undefined);

func:
// ======================================================
// NODE: Fronius Werte auswerten
// Zweck:
// - Fronius PowerFlow API auswerten
// - SOC, Hauslast, PV-Leistung und Batterie-Leistung lesen
// - Werte zusätzlich im flow-Speicher ablegen
// - Keine node.warn Ausgaben: Debug nur über Debug-Node
// ======================================================

const data = msg.payload?.Body?.Data;
const site = data?.Site || {};
const inverters = data?.Inverters || {};

// Ersten Inverter suchen
const firstInvKey = Object.keys(inverters)[0];
const inv = firstInvKey ? inverters[firstInvKey] : {};

// Rohwerte aus Fronius API
const soc = Number(inv.SOC);
const batteryMode = inv.Battery_Mode ?? null;

const pPv = Number(site.P_PV ?? 0);
const pLoadRaw = Number(site.P_Load ?? 0);
const pGrid = Number(site.P_Grid ?? 0);
const pAkkuRaw = Number(site.P_Akku ?? 0);

// Fronius P_Load ist häufig negativ für Verbrauch.
// Für unsere Logik wollen wir Hausverbrauch positiv in W.
const houseLoadW = Math.abs(pLoadRaw);

// V5/Victron-Anzeige-Konvention aus unserer PDF:
// Laden positiv, Entladen negativ.
// Fronius P_Akku muss ggf. später geprüft werden.
// Aktuell übernehmen wir den Rohwert separat und berechnen Anzeige konservativ.
const batteryPowerRawW = pAkkuRaw;
const batteryPowerDisplayW = pAkkuRaw;

// Validierung
const socValid = Number.isFinite(soc);
const houseLoadValid = Number.isFinite(houseLoadW);

// In flow-Speicher schreiben
if (socValid) {
    flow.set("$parent.soc_percent", soc);
}

if (houseLoadValid) {
    flow.set("$parent.house_load_w", houseLoadW);
}

flow.set("$parent.pv_power_w", Number.isFinite(pPv) ? pPv : 0);
flow.set("$parent.grid_power_w", Number.isFinite(pGrid) ? pGrid : 0);
flow.set("$parent.battery_power_raw_w", Number.isFinite(batteryPowerRawW) ? batteryPowerRawW : 0);
flow.set("$parent.battery_mode", batteryMode);

// Debug-/Status-Payload
msg.payload = {
    ok: socValid && houseLoadValid,
    source: "fronius_powerflow",
    soc_percent: socValid ? soc : null,
    battery_mode: batteryMode,
    house_load_w: houseLoadValid ? houseLoadW : null,
    pv_power_w: Number.isFinite(pPv) ? pPv : null,
    grid_power_w: Number.isFinite(pGrid) ? pGrid : null,
    battery_power_raw_w: Number.isFinite(batteryPowerRawW) ? batteryPowerRawW : null,
    battery_power_display_w: Number.isFinite(batteryPowerDisplayW) ? batteryPowerDisplayW : null,
    raw: {
        P_Load: pLoadRaw,
        P_Grid: pGrid,
        P_Akku: pAkkuRaw,
        P_PV: pPv
    }
};

return msg;

// ======================================================
// NODE: Verto_HTTP_auswerten
// Zweck:
// - Fronius PowerFlowRealtimeData auswerten
// - P_Grid, P_Load, P_PV, P_Akku und SOC robust extrahieren
// - Werte im flow context speichern
// - KEINE Regelentscheidung hier
// ======================================================

const DEBUG = true;

// ------------------------------------------------------
// Hilfsfunktionen
// ------------------------------------------------------
function asNumber(v) {
    if (v === null || v === undefined) return null;
    const n = Number(v);
    return Number.isFinite(n) ? n : null;
}

function pickNumber(...values) {
    for (const v of values) {
        const n = asNumber(v);
        if (n !== null) return n;
    }
    return null;
}

// ------------------------------------------------------
// Fronius PowerFlow Struktur
// ------------------------------------------------------
const data = msg.payload?.Body?.Data || {};
const site = data.Site || {};
const inverters = data.Inverters || {};

// Meist gibt es nur Inverter "1"
const inv1 =
    inverters["1"] ||
    inverters[1] ||
    Object.values(inverters)[0] ||
    {};

// ------------------------------------------------------
// Werte lesen
// ------------------------------------------------------

// P_Grid:
// typischerweise:
//   > 0 = Netzbezug
//   < 0 = Einspeisung
const gridPowerW = pickNumber(
    site.P_Grid,
    msg.grid_power_w,
    msg.payload?.grid_power_w
);

// P_Load:
// bei Fronius oft negativ, wir speichern Hausverbrauch positiv
const pLoadRaw = pickNumber(
    site.P_Load,
    msg.house_load_w,
    msg.payload?.house_load_w
);

const houseLoadW = pLoadRaw !== null ? Math.abs(pLoadRaw) : null;

const pvPowerW = pickNumber(
    site.P_PV,
    msg.pv_power_w,
    msg.payload?.pv_power_w
);

// P_Akku / P_Battery:
// Vorzeichen kann je nach Fronius-Ansicht unterschiedlich sein.
// Wir speichern erstmal roh und ändern NICHTS blind.
const batteryPowerRawW = pickNumber(
    site.P_Akku,
    site.P_Battery,
    msg.battery_power_raw_w,
    msg.payload?.battery_power_raw_w
);

// SOC kann je nach Endpoint im Inverter-Block oder Site liegen
const socPercent = pickNumber(
    inv1.SOC,
    site.SOC,
    msg.soc_percent,
    msg.payload?.soc_percent
);

// Battery Mode, falls vorhanden
const batteryMode =
    inv1.Battery_Mode ||
    inv1.battery_mode ||
    site.Battery_Mode ||
    msg.battery_mode ||
    msg.payload?.battery_mode ||
    null;

// ------------------------------------------------------
// Plausibilitätscheck
// ------------------------------------------------------
if (gridPowerW === null) {
    node.error("P_Grid / grid_power_w nicht gefunden", msg);
    return null;
}

if (houseLoadW === null) {
    node.warn("P_Load / house_load_w nicht gefunden, Regelung kann später nur mit P_Grid arbeiten");
}

// ------------------------------------------------------
// flow context speichern
// ------------------------------------------------------
flow.set("$parent.fronius_grid_power_w", gridPowerW);
flow.set("$parent.fronius_house_load_w", houseLoadW);
flow.set("$parent.fronius_pv_power_w", pvPowerW);
flow.set("$parent.fronius_battery_power_raw_w", batteryPowerRawW);
flow.set("$parent.fronius_soc_percent", socPercent);
flow.set("$parent.fronius_battery_mode", batteryMode);
flow.set("$parent.fronius_http_last_seen", Date.now());

// Für spätere Functions auch auf msg schreiben
msg.ok = true;
msg.source = "fronius_powerflow";

msg.grid_power_w = gridPowerW;
msg.house_load_w = houseLoadW;
msg.pv_power_w = pvPowerW;
msg.battery_power_raw_w = batteryPowerRawW;
msg.soc_percent = socPercent;
msg.battery_mode = batteryMode;

if (DEBUG) {
    msg.debug_fronius = {
        grid_power_w: gridPowerW,
        grid_meaning:
            gridPowerW > 0 ? "Netzbezug" :
            gridPowerW < 0 ? "Einspeisung" :
            "Null",
        house_load_w: houseLoadW,
        pv_power_w: pvPowerW,
        battery_power_raw_w: batteryPowerRawW,
        soc_percent: socPercent,
        battery_mode: batteryMode,
        last_seen: new Date().toISOString()
    };
}

return msg;

// ======================================================
// NODE: Forecast_auswerten_V6
// Zweck:
// - forecast.solar Response auswerten
// - result.watt_hours_period pro Europe/Vienna-Kalendertag summieren
// - heute, morgen, übermorgen in kWh berechnen
// - Werte im flow-Speicher ablegen
// - V6: noch keine finale Steuerentscheidung, nur Forecast-Daten
// ======================================================

function viennaDateString(offsetDays = 0) {
    const fmt = new Intl.DateTimeFormat("sv-SE", {
        timeZone: "Europe/Vienna",
        year: "numeric",
        month: "2-digit",
        day: "2-digit"
    });

    const now = new Date();
    const todayStr = fmt.format(now);

    // Mittagszeit verhindert DST-/Zeitzonen-Kantenprobleme
    const base = new Date(`${todayStr}T12:00:00`);
    base.setDate(base.getDate() + offsetDays);

    return fmt.format(base);
}

function round1(x) {
    return Math.round(x * 10) / 10;
}

function sumWhForDate(wattHoursPeriod, dateStr) {
    let sumWh = 0;
    let points = 0;

    for (const [ts, whRaw] of Object.entries(wattHoursPeriod || {})) {
        if (!ts.startsWith(dateStr)) continue;

        const wh = Number(whRaw);
        if (!Number.isFinite(wh)) continue;

        sumWh += wh;
        points++;
    }

    return {
        kwh: round1(sumWh / 1000),
        points
    };
}

// Payload robust behandeln
let payload = msg.payload;

if (typeof payload === "string") {
    try {
        payload = JSON.parse(payload);
    } catch (e) {
        payload = {};
    }
}

const whPeriod = payload?.result?.watt_hours_period;

const todayDate = viennaDateString(0);
const tomorrowDate = viennaDateString(1);
const dayAfterTomorrowDate = viennaDateString(2);

let source = "forecast.solar/watt_hours_period";
let usedFallback = false;

let today = { kwh: 0, points: 0 };
let tomorrow = { kwh: 0, points: 0 };
let dayAfterTomorrow = { kwh: 0, points: 0 };

if (whPeriod && typeof whPeriod === "object") {
    today = sumWhForDate(whPeriod, todayDate);
    tomorrow = sumWhForDate(whPeriod, tomorrowDate);
    dayAfterTomorrow = sumWhForDate(whPeriod, dayAfterTomorrowDate);

    if (today.points + tomorrow.points + dayAfterTomorrow.points === 0) {
        usedFallback = true;
        source = "fallback_no_matching_dates";
    }
} else {
    usedFallback = true;
    source = "fallback_missing_watt_hours_period";
}

// Flow-Speicher für Strategie_V6
flow.set("$parent.forecast_today_kwh", today.kwh);
flow.set("$parent.forecast_tomorrow_kwh", tomorrow.kwh);
flow.set("$parent.forecast_day_after_tomorrow_kwh", dayAfterTomorrow.kwh);

flow.set("$parent.forecast_today_date", todayDate);
flow.set("$parent.forecast_tomorrow_date", tomorrowDate);
flow.set("$parent.forecast_day_after_tomorrow_date", dayAfterTomorrowDate);

flow.set("$parent.forecast_source", source);
flow.set("$parent.forecast_used_fallback", usedFallback);
flow.set("$parent.forecast_updated_at", new Date().toISOString());

// Abwärtskompatibel für alte Nodes
flow.set("$parent.forecast_kwh", today.kwh);
flow.set("$parent.forecast_date", todayDate);

// Debug-Ausgabe
msg.payload = {
    ok: !usedFallback,
    source,
    used_fallback: usedFallback,
    forecast: {
        today: {
            date: todayDate,
            kwh: today.kwh,
            points: today.points
        },
        tomorrow: {
            date: tomorrowDate,
            kwh: tomorrow.kwh,
            points: tomorrow.points
        },
        day_after_tomorrow: {
            date: dayAfterTomorrowDate,
            kwh: dayAfterTomorrow.kwh,
            points: dayAfterTomorrow.points
        }
    }
};

return msg;

// ======================================================
// NODE: Strategie_V7.4
//
// Bereinigte Strategie:
// - Ziel-SOC aus HEUTE + MORGEN, schlechtere Klasse gewinnt
// - strategische Entladung relativ zum Sonnenaufgang
// - keine SOC-Toleranz: exakt am Ziel-SOC stoppen
// - Ladeblock ab Sonnenaufgang
// - Ladeblock ab Ziel-SOC; unter Ziel darf bis Ziel geladen werden
// - Ladebegrenzung nur nach Forecast HEUTE
// - normale Hauslast regelt Fronius selbst
// - Hauslast dient nur als Mindest-Floor bei Zwangsentladung
// - externe Entladesperre gibt den Verto vollständig frei
// ======================================================

const CONFIG_KEY = "strategy_v7_config";
const WRTE_MAX = 10000;

// Sicherheits-Fallback nur falls Sonnenaufgang nicht berechnet werden kann.
// Standort ist normalerweise immer aus der Config vorhanden.
const FALLBACK_DISCHARGE_START_MIN = 4 * 60 + 30; // 04:30
const FALLBACK_DISCHARGE_END_MIN   = 8 * 60;      // 08:00

// ------------------------------------------------------
// Hilfsfunktionen
// ------------------------------------------------------

const clamp = (v, min, max) =>
    Math.min(Math.max(Number(v), min), max);

const round0 = v => Math.round(Number(v) || 0);
const round1 = v => Math.round((Number(v) || 0) * 10) / 10;

function finite(value) {
    if (value === null || value === undefined || value === "") return null;
    const n = Number(value);
    return Number.isFinite(n) ? n : null;
}

function normMin(value) {
    return ((Math.round(Number(value) || 0) % 1440) + 1440) % 1440;
}

function hhmm(value) {
    if (value === null || value === undefined || !Number.isFinite(Number(value))) {
        return null;
    }

    const m = normMin(value);
    return (
        String(Math.floor(m / 60)).padStart(2, "0") +
        ":" +
        String(m % 60).padStart(2, "0")
    );
}

function inWindow(now, start, end) {
    now = normMin(now);
    start = normMin(start);
    end = normMin(end);

    if (start === end) return false;

    return start < end
        ? now >= start && now < end
        : now >= start || now < end;
}

function minutesUntil(now, end) {
    let diff = normMin(end) - normMin(now);
    if (diff < 0) diff += 1440;
    return diff;
}

// ------------------------------------------------------
// Europe/Vienna Zeit
// ------------------------------------------------------

function viennaMinutes() {
    const text = new Intl.DateTimeFormat("sv-SE", {
        timeZone: "Europe/Vienna",
        hour: "2-digit",
        minute: "2-digit",
        hour12: false
    }).format(new Date());

    const [h, m] = text.split(":").map(Number);
    return h * 60 + m;
}

function viennaDateTime() {
    return new Intl.DateTimeFormat("sv-SE", {
        timeZone: "Europe/Vienna",
        year: "numeric",
        month: "2-digit",
        day: "2-digit",
        hour: "2-digit",
        minute: "2-digit",
        second: "2-digit",
        hour12: false
    })
        .format(new Date())
        .replace(" ", "T");
}

function viennaDateParts() {
    const parts = new Intl.DateTimeFormat("en-CA", {
        timeZone: "Europe/Vienna",
        year: "numeric",
        month: "2-digit",
        day: "2-digit"
    }).formatToParts(new Date());

    const out = {};

    for (const part of parts) {
        if (part.type !== "literal") {
            out[part.type] = Number(part.value);
        }
    }

    return {
        year: out.year,
        month: out.month,
        day: out.day
    };
}

// ------------------------------------------------------
// Sonnenaufgang
// NOAA-ähnliche Näherung wie bisher
// ------------------------------------------------------

const d2r = v => v * Math.PI / 180;
const r2d = v => v * 180 / Math.PI;
const normDeg = v => ((v % 360) + 360) % 360;

function dayOfYear(year, month, day) {
    return Math.floor(
        (
            Date.UTC(year, month - 1, day) -
            Date.UTC(year, 0, 0)
        ) / 86400000
    );
}

function sunriseUTC(year, month, day, lat, lon) {
    if (!Number.isFinite(lat) || !Number.isFinite(lon)) return null;

    const n = dayOfYear(year, month, day);
    const lngHour = lon / 15;
    const t = n + ((6 - lngHour) / 24);

    const M = 0.9856 * t - 3.289;

    const L = normDeg(
        M +
        1.916 * Math.sin(d2r(M)) +
        0.020 * Math.sin(d2r(2 * M)) +
        282.634
    );

    let RA = normDeg(
        r2d(
            Math.atan(
                0.91764 * Math.tan(d2r(L))
            )
        )
    );

    RA += Math.floor(L / 90) * 90 - Math.floor(RA / 90) * 90;
    RA /= 15;

    const sinDec = 0.39782 * Math.sin(d2r(L));
    const cosDec = Math.cos(Math.asin(sinDec));

    const cosH =
        (
            Math.cos(d2r(90.833)) -
            sinDec * Math.sin(d2r(lat))
        ) /
        (
            cosDec * Math.cos(d2r(lat))
        );

    if (cosH > 1 || cosH < -1) return null;

    const H = (360 - r2d(Math.acos(cosH))) / 15;
    const localMeanTime = H + RA - 0.06571 * t - 6.622;

    let utcHour = localMeanTime - lngHour;
    while (utcHour < 0) utcHour += 24;
    while (utcHour >= 24) utcHour -= 24;

    return new Date(
        Date.UTC(year, month - 1, day) +
        utcHour * 3600000
    );
}

function dateToViennaMinutes(date) {
    if (!(date instanceof Date) || Number.isNaN(date.getTime())) return null;

    const text = new Intl.DateTimeFormat("sv-SE", {
        timeZone: "Europe/Vienna",
        hour: "2-digit",
        minute: "2-digit",
        hour12: false
    }).format(date);

    const [h, m] = text.split(":").map(Number);
    return h * 60 + m;
}

// ------------------------------------------------------
// Config
// ------------------------------------------------------

const cfg = flow.get(CONFIG_KEY);

if (!cfg || typeof cfg !== "object") {
    msg.payload = {
        ok: false,
        error: "strategy_v7_config fehlt",
        modbus_proposal: {
            write_active: true,
            storctl_mod: 0,
            outwrte: 10000,
            inwrte: 10000,
            mode_reason: "config_missing_verto_free"
        },
        write: {
            storctl_mod: 0,
            outwrte: 10000,
            inwrte: 10000
        }
    };

    node.status({
        fill: "red",
        shape: "ring",
        text: "V7.4 Config fehlt → Verto frei"
    });

    return msg;
}

// ------------------------------------------------------
// Simulation
// ------------------------------------------------------

const sim = msg.payload?.sim === true;
const si = sim ? msg.payload : {};

// ------------------------------------------------------
// Konfiguration
// ------------------------------------------------------

const BATTERY_CAPACITY_KWH = Number(cfg.battery.capacity_kwh);
const BATTERY_POWER_REF_W = Number(cfg.battery.power_ref_w);

const DISCHARGE_ENABLED = cfg.discharge.enabled === true;
const DISCHARGE_OFFSET_MIN = Number(cfg.discharge.sunrise_offset_min);
const DISCHARGE_END_OFFSET_MIN = Number(cfg.discharge.sunrise_end_offset_min);
const MAX_DISCHARGE_POWER_W = Number(cfg.discharge.max_power_w);
const HOUSE_LOAD_MARGIN_W = Number(cfg.discharge.house_load_margin_w ?? 200);

const MIN_SOC = Number(cfg.reserve.min_soc_absolute);
const VERY_BAD_BELOW = Number(cfg.reserve.very_bad_below_kwh);
const TARGET_VERY_BAD = Number(cfg.reserve.target_soc_very_bad);
const WEAK_BELOW = Number(cfg.reserve.weak_below_kwh);
const TARGET_WEAK = Number(cfg.reserve.target_soc_weak);
const MEDIUM_BELOW = Number(cfg.reserve.medium_below_kwh);
const TARGET_MEDIUM = Number(cfg.reserve.target_soc_medium);
const TARGET_GOOD = Number(cfg.reserve.target_soc_good);

const CHARGE_BLOCK_ENABLED = cfg.charge_block.enabled === true;
const CHARGE_BLOCK_DURATION_MIN = Number(cfg.charge_block.duration_min);
const CHARGE_BLOCK_MIN_TODAY_KWH = Number(cfg.charge_block.min_today_kwh);

const CHARGE_LIMIT_ENABLED = cfg.charge_limit.enabled === true;
const VERY_GOOD_TODAY = Number(cfg.charge_limit.very_good_today_min_kwh);
const VERY_GOOD_PERCENT = Number(cfg.charge_limit.very_good_percent);
const GOOD_TODAY = Number(cfg.charge_limit.good_today_min_kwh);
const GOOD_PERCENT = Number(cfg.charge_limit.good_percent);
const MEDIUM_TODAY = Number(cfg.charge_limit.medium_today_min_kwh);
const MEDIUM_PERCENT = Number(cfg.charge_limit.medium_percent);
const WEAK_PERCENT = Number(cfg.charge_limit.weak_percent);

const wattsToWrte = watts =>
    clamp(
        Math.round(
            Number(watts) / BATTERY_POWER_REF_W * WRTE_MAX
        ),
        0,
        WRTE_MAX
    );

const wrteToWatts = wrte =>
    Math.round(
        Number(wrte) / WRTE_MAX * BATTERY_POWER_REF_W
    );

// ------------------------------------------------------
// Zeit / Sonnenaufgang
// ------------------------------------------------------

const nowMinutes =
    sim && finite(si.vienna_minutes) !== null
        ? normMin(si.vienna_minutes)
        : viennaMinutes();

let sunriseMinutes = null;
let sunriseSource = "fallback";

if (sim && finite(si.sunrise_minutes) !== null) {
    sunriseMinutes = normMin(si.sunrise_minutes);
    sunriseSource = "simulation";
}
else {
    const lat = finite(cfg.location?.latitude);
    const lon = finite(cfg.location?.longitude);

    if (lat !== null && lon !== null) {
        const d = viennaDateParts();

        sunriseMinutes = dateToViennaMinutes(
            sunriseUTC(
                d.year,
                d.month,
                d.day,
                lat,
                lon
            )
        );

        if (sunriseMinutes !== null) {
            sunriseSource = "calculated";
        }
    }
}

const dischargeStart =
    sunriseMinutes !== null
        ? normMin(sunriseMinutes - DISCHARGE_OFFSET_MIN)
        : FALLBACK_DISCHARGE_START_MIN;

const dischargeEnd =
    sunriseMinutes !== null
        ? normMin(sunriseMinutes + DISCHARGE_END_OFFSET_MIN)
        : normMin(
            FALLBACK_DISCHARGE_END_MIN +
            DISCHARGE_END_OFFSET_MIN
        );

const inDischargeWindow =
    DISCHARGE_ENABLED &&
    inWindow(
        nowMinutes,
        dischargeStart,
        dischargeEnd
    );

const chargeBlockStart =
    sunriseMinutes !== null
        ? sunriseMinutes
        : FALLBACK_DISCHARGE_END_MIN;

const chargeBlockEnd =
    normMin(
        chargeBlockStart +
        CHARGE_BLOCK_DURATION_MIN
    );

const inChargeBlockWindow =
    CHARGE_BLOCK_ENABLED &&
    inWindow(
        nowMinutes,
        chargeBlockStart,
        chargeBlockEnd
    );

// ------------------------------------------------------
// Externe Entladesperre
// ------------------------------------------------------

const externalDischargeLock =
    (sim && si.entladen_sperren === true) ||
    msg.entladen_sperren === true ||
    msg.payload?.entladen_sperren === true ||
    flow.get("verto_discharge_lock") === true;

const lockSources =
    flow.get("verto_discharge_lock_sources") ||
    (
        msg.lock_source
            ? [msg.lock_source]
            : []
    );

const allLocks =
    flow.get("verto_discharge_locks") ||
    {};

// ------------------------------------------------------
// Forecast
// ------------------------------------------------------

const todayKwh =
    sim
        ? finite(si.forecast_today_kwh)
        : finite(flow.get("forecast_today_kwh"));

const tomorrowKwh =
    sim
        ? finite(si.forecast_tomorrow_kwh)
        : finite(flow.get("forecast_tomorrow_kwh"));

const todayDate =
    flow.get("forecast_today_date") ??
    null;

const tomorrowDate =
    flow.get("forecast_tomorrow_date") ??
    null;

const forecastSource =
    flow.get("forecast_source") ??
    "unknown";

const forecastFallback =
    sim
        ? false
        : Boolean(
            flow.get("forecast_used_fallback")
        );

const todayForecastValid =
    todayKwh !== null &&
    !forecastFallback;

const reserveForecastValid =
    todayKwh !== null &&
    tomorrowKwh !== null &&
    !forecastFallback;

// ------------------------------------------------------
// Livewerte
// ------------------------------------------------------

const soc =
    sim
        ? finite(si.soc_percent)
        : finite(flow.get("soc_percent"));

const houseLoadW =
    sim
        ? finite(si.house_load_w)
        : finite(flow.get("house_load_w"));

const pvPowerW =
    sim
        ? finite(si.pv_power_w)
        : finite(flow.get("pv_power_w"));

const gridPowerW =
    sim
        ? finite(si.grid_power_w)
        : finite(flow.get("grid_power_w"));

const batteryPowerW =
    sim
        ? finite(si.battery_power_w)
        : finite(flow.get("battery_power_w"));

const batteryMode =
    sim
        ? "simulation"
        : (flow.get("battery_mode") ?? null);

const socValid = soc !== null;
const houseLoadValid = houseLoadW !== null;
const gridPowerValid = gridPowerW !== null;

// ------------------------------------------------------
// Reserve / Ziel-SOC
//
// HEUTE und MORGEN werden identisch klassifiziert.
// Die schlechtere Klasse gewinnt.
// ------------------------------------------------------

function reserveClassFor(kwh) {
    if (kwh < VERY_BAD_BELOW) {
        return {
            rank: 3,
            name: "VERY_BAD",
            targetSoc: TARGET_VERY_BAD
        };
    }

    if (kwh < WEAK_BELOW) {
        return {
            rank: 2,
            name: "WEAK",
            targetSoc: TARGET_WEAK
        };
    }

    if (kwh < MEDIUM_BELOW) {
        return {
            rank: 1,
            name: "MEDIUM",
            targetSoc: TARGET_MEDIUM
        };
    }

    return {
        rank: 0,
        name: "GOOD",
        targetSoc: TARGET_GOOD
    };
}

let reserveClass = "UNKNOWN";
let todayReserveClass = "UNKNOWN";
let tomorrowReserveClass = "UNKNOWN";
let targetSoc = clamp(TARGET_VERY_BAD, MIN_SOC, 100);
let reserveReason = "forecast_invalid_safe_target";

if (reserveForecastValid) {
    const todayReserve = reserveClassFor(todayKwh);
    const tomorrowReserve = reserveClassFor(tomorrowKwh);

    todayReserveClass = todayReserve.name;
    tomorrowReserveClass = tomorrowReserve.name;

    const combined =
        todayReserve.rank >= tomorrowReserve.rank
            ? todayReserve
            : tomorrowReserve;

    reserveClass = combined.name;
    targetSoc = clamp(combined.targetSoc, MIN_SOC, 100);
    reserveReason = "worse_class_of_today_and_tomorrow";
}

// ------------------------------------------------------
// Strategische Entladung
// ------------------------------------------------------

let strategicAllowed = false;
let strategicReason = "not_evaluated";
let energyToTargetKwh = 0;
let hoursUntilDischargeEnd = 0;
let calculatedDischargeW = 0;
let requiredDischargeW = 0;

const socAboveTarget =
    socValid
        ? Math.max(0, soc - targetSoc)
        : 0;

if (externalDischargeLock) {
    strategicReason = "external_discharge_lock";
}
else if (!DISCHARGE_ENABLED) {
    strategicReason = "strategic_discharge_disabled";
}
else if (!reserveForecastValid) {
    strategicReason = "forecast_invalid_no_strategic_discharge";
}
else if (!socValid) {
    strategicReason = "soc_missing_no_strategic_discharge";
}
else if (!inDischargeWindow) {
    strategicReason = "outside_discharge_window";
}
else if (soc <= targetSoc) {
    strategicReason = "target_soc_reached_stop_discharge";
}
else {
    hoursUntilDischargeEnd =
        Math.max(
            1,
            minutesUntil(
                nowMinutes,
                dischargeEnd
            )
        ) / 60;

    energyToTargetKwh =
        BATTERY_CAPACITY_KWH *
        socAboveTarget /
        100;

    calculatedDischargeW =
        energyToTargetKwh /
        hoursUntilDischargeEnd *
        1000;

    requiredDischargeW =
        Math.min(
            calculatedDischargeW,
            MAX_DISCHARGE_POWER_W,
            BATTERY_POWER_REF_W
        );

    if (requiredDischargeW > 0) {
        strategicAllowed = true;
        strategicReason =
            "dynamic_discharge_to_target_by_discharge_end";
    }
}

// ------------------------------------------------------
// Hauslast-Floor nur während strategischer Entladung
// ------------------------------------------------------

const houseFloorW =
    strategicAllowed &&
    houseLoadValid &&
    houseLoadW > 0
        ? Math.max(
            0,
            houseLoadW +
            HOUSE_LOAD_MARGIN_W
        )
        : 0;

let totalDischargeW = 0;
let totalOutwrte = 0;

if (strategicAllowed) {
    totalDischargeW =
        clamp(
            Math.max(
                requiredDischargeW,
                houseFloorW
            ),
            0,
            BATTERY_POWER_REF_W
        );

    totalOutwrte =
        wattsToWrte(
            totalDischargeW
        );
}

// ------------------------------------------------------
// Ladeblock
//
// Keine zusätzliche SOC-Toleranz mehr:
// - SOC < Ziel: Laden bis Ziel erlaubt
// - SOC >= Ziel: Ladeblock darf greifen
// ------------------------------------------------------

let chargeBlockAllowed = false;
let chargeBlockReason = "not_evaluated";

if (externalDischargeLock) {
    chargeBlockReason = "external_discharge_lock";
}
else if (!CHARGE_BLOCK_ENABLED) {
    chargeBlockReason = "charge_block_disabled";
}
else if (!todayForecastValid) {
    chargeBlockReason = "forecast_invalid_no_charge_block";
}
else if (!socValid) {
    chargeBlockReason = "soc_missing_no_charge_block";
}
else if (!inChargeBlockWindow) {
    chargeBlockReason = "outside_charge_block_window";
}
else if (todayKwh < CHARGE_BLOCK_MIN_TODAY_KWH) {
    chargeBlockReason = "today_forecast_too_low_no_charge_block";
}
else if (soc < targetSoc) {
    chargeBlockReason = "soc_below_target_charge_to_target_allowed";
}
else {
    chargeBlockAllowed = true;
    chargeBlockReason = "sunrise_charge_block_active";
}

// ------------------------------------------------------
// Ladebegrenzung nur nach HEUTE
// ------------------------------------------------------

let chargeClass = "WEAK";
let maxChargePercent = 100;
let chargeLimitReason = "not_evaluated";

if (!CHARGE_LIMIT_ENABLED) {
    chargeClass = "OFF";
    maxChargePercent = 100;
    chargeLimitReason = "charge_limit_disabled";
}
else if (!todayForecastValid) {
    chargeClass = "WEAK";
    maxChargePercent = 100;
    chargeLimitReason = "forecast_invalid_charge_unlimited";
}
else if (todayKwh >= VERY_GOOD_TODAY) {
    chargeClass = "VERY_GOOD";
    maxChargePercent = VERY_GOOD_PERCENT;
    chargeLimitReason = "very_good_forecast";
}
else if (todayKwh >= GOOD_TODAY) {
    chargeClass = "GOOD";
    maxChargePercent = GOOD_PERCENT;
    chargeLimitReason = "good_forecast";
}
else if (todayKwh >= MEDIUM_TODAY) {
    chargeClass = "MEDIUM";
    maxChargePercent = MEDIUM_PERCENT;
    chargeLimitReason = "medium_forecast";
}
else {
    chargeClass = "WEAK";
    maxChargePercent = WEAK_PERCENT;
    chargeLimitReason = "weak_forecast";
}

maxChargePercent =
    clamp(
        maxChargePercent,
        0,
        100
    );

const maxChargeWrte =
    Math.round(
        maxChargePercent * 100
    );

const chargeLimitActive =
    !externalDischargeLock &&
    CHARGE_LIMIT_ENABLED &&
    todayForecastValid &&
    maxChargeWrte < WRTE_MAX;

// ------------------------------------------------------
// Modbus-Priorität
//
// 0. externe Entladesperre -> Verto frei
// 1. strategische Entladung
// 2. Ladeblock
// 3. Ladebegrenzung
// 4. Fronius frei
// ------------------------------------------------------

let storctl = 0;
let outwrte = 10000;
let inwrte = 10000;
let modeReason = "verto_free_self_consumption_control";

if (externalDischargeLock) {
    storctl = 0;
    outwrte = 10000;
    inwrte = 10000;
    modeReason = "external_discharge_lock_verto_free";
}
else if (strategicAllowed && totalOutwrte > 0) {
    storctl = 3;
    outwrte = totalOutwrte;
    inwrte = -totalOutwrte;
    modeReason =
        "forced_dynamic_discharge_to_target_by_discharge_end";
}
else if (chargeBlockAllowed) {
    storctl = 1;
    outwrte = 10000;
    inwrte = 0;
    modeReason =
        "charge_block_only_fronius_controls_discharge";
}
else if (chargeLimitActive) {
    storctl = 1;
    outwrte = 10000;
    inwrte = maxChargeWrte;
    modeReason =
        "forecast_charge_limit_only_fronius_controls_discharge";
}

// ------------------------------------------------------
// Flow-Werte / Kompatibilität
// ------------------------------------------------------

if (!sim) {
    const values = {
        external_discharge_lock_active: externalDischargeLock,
        reserve_class: reserveClass,
        reserve_today_class: todayReserveClass,
        reserve_tomorrow_class: tomorrowReserveClass,
        target_soc: targetSoc,
        strategic_discharge_allowed: strategicAllowed,
        charge_block_allowed: chargeBlockAllowed,
        charge_limit_is_active: chargeLimitActive,
        charge_limit_class: chargeClass,
        max_charge_wrte: maxChargeWrte,
        required_target_discharge_w: requiredDischargeW,
        total_battery_discharge_w: totalDischargeW,
        sunrise_min: sunriseMinutes,
        sunrise_source: sunriseSource,
        discharge_start_min: dischargeStart,
        discharge_end_min: dischargeEnd,
        charge_block_start_min: chargeBlockStart,
        charge_block_end_min: chargeBlockEnd,
        modbus_mode_reason: modeReason
    };

    for (const [key, value] of Object.entries(values)) {
        flow.set(
            "strategy_v7_" + key,
            value
        );
    }

    // Bestehender Downstream / Modbus_Befehle_bauen
    flow.set("storctl_mod", storctl);
    flow.set("outwrte", outwrte);
    flow.set("inwrte", inwrte);
}

const writeActive =
    !sim &&
    (externalDischargeLock || socValid) &&
    Number.isFinite(storctl) &&
    Number.isFinite(outwrte) &&
    Number.isFinite(inwrte);

// ------------------------------------------------------
// Output
// ------------------------------------------------------

msg.payload = {
    ok:
        socValid &&
        todayForecastValid &&
        reserveForecastValid,

    mode:
        sim
            ? "simulation_v7_4"
            : "v7_4_dynamic_sunrise",

    simulation: {
        active: sim,
        write_suppressed: sim
    },

    external_discharge_lock: {
        active: externalDischargeLock,
        sources: lockSources,
        all_locks: allLocks,
        reason:
            externalDischargeLock
                ? "entladen_sperren_aktiv"
                : "not_active"
    },

    time: {
        vienna_now:
            sim
                ? "SIM " + hhmm(nowMinutes)
                : viennaDateTime(),

        minutes: nowMinutes,
        hhmm: hhmm(nowMinutes),

        sunrise:
            sunriseMinutes === null
                ? null
                : hhmm(sunriseMinutes),

        sunrise_minutes: sunriseMinutes,
        sunrise_source: sunriseSource,

        in_discharge_window: inDischargeWindow,
        discharge_start: hhmm(dischargeStart),
        discharge_end: hhmm(dischargeEnd),
        discharge_window:
            hhmm(dischargeStart) +
            "-" +
            hhmm(dischargeEnd),

        charge_block_start: hhmm(chargeBlockStart),
        charge_block_end: hhmm(chargeBlockEnd),
        charge_block_window:
            hhmm(chargeBlockStart) +
            "-" +
            hhmm(chargeBlockEnd)
    },

    inputs: {
        forecast_today_date: todayDate,
        forecast_today_kwh:
            todayKwh === null ? null : round1(todayKwh),

        forecast_tomorrow_date: tomorrowDate,
        forecast_tomorrow_kwh:
            tomorrowKwh === null ? null : round1(tomorrowKwh),

        forecast_source: forecastSource,
        forecast_used_fallback: forecastFallback,

        soc_percent:
            socValid ? round1(soc) : null,

        house_load_w:
            houseLoadValid ? round0(houseLoadW) : null,

        pv_power_w:
            pvPowerW !== null ? round0(pvPowerW) : null,

        grid_power_w:
            gridPowerValid ? round0(gridPowerW) : null,

        battery_power_w:
            batteryPowerW !== null ? round0(batteryPowerW) : null,

        battery_mode: batteryMode
    },

    reserve: {
        reserve_class: reserveClass,
        today_class: todayReserveClass,
        tomorrow_class: tomorrowReserveClass,
        target_soc: targetSoc,
        min_soc_absolute: MIN_SOC,
        reason: reserveReason
    },

    strategic_discharge: {
        enabled: DISCHARGE_ENABLED,
        allowed: strategicAllowed,
        reason: strategicReason,

        soc_above_target_percent:
            round1(socAboveTarget),

        energy_to_target_kwh:
            round1(energyToTargetKwh),

        hours_until_discharge_end:
            round1(hoursUntilDischargeEnd),

        calculated_discharge_w:
            round0(calculatedDischargeW),

        max_discharge_power_w:
            MAX_DISCHARGE_POWER_W,

        required_target_discharge_w:
            round0(requiredDischargeW),

        house_load_floor_w:
            round0(houseFloorW),

        house_load_margin_w:
            HOUSE_LOAD_MARGIN_W
    },

    charge_block: {
        enabled: CHARGE_BLOCK_ENABLED,
        allowed: chargeBlockAllowed,
        reason: chargeBlockReason,
        start: hhmm(chargeBlockStart),
        until: hhmm(chargeBlockEnd),
        duration_min: CHARGE_BLOCK_DURATION_MIN,
        min_today_kwh: CHARGE_BLOCK_MIN_TODAY_KWH
    },

    charge_limit: {
        enabled: CHARGE_LIMIT_ENABLED,
        active: chargeLimitActive,
        class: chargeClass,
        max_charge_percent: round1(maxChargePercent),
        max_charge_wrte: maxChargeWrte,
        estimated_max_charge_power_w:
            wrteToWatts(maxChargeWrte),
        reason:
            externalDischargeLock
                ? "external_discharge_lock"
                : chargeLimitReason
    },

    discharge_command: {
        battery_capacity_kwh: BATTERY_CAPACITY_KWH,
        battery_power_ref_w: BATTERY_POWER_REF_W,
        total_battery_discharge_w:
            round0(totalDischargeW),
        total_outwrte: totalOutwrte,
        total_outwrte_percent:
            round1(totalOutwrte / 100),
        estimated_power_from_outwrte_w:
            wrteToWatts(totalOutwrte)
    },

    modbus_proposal: {
        write_active: writeActive,
        storctl_mod: storctl,
        outwrte,
        inwrte,
        mode_reason: modeReason,

        safety: {
            today_forecast_valid: todayForecastValid,
            reserve_forecast_valid: reserveForecastValid,
            soc_valid: socValid,
            grid_power_valid: gridPowerValid,
            house_load_valid: houseLoadValid,
            simulation_write_blocked: sim
        }
    },

    // Kompatibel mit Modbus_Befehle_bauen
    write: {
        storctl_mod: storctl,
        outwrte,
        inwrte
    }
};

// ------------------------------------------------------
// Node Status
// ------------------------------------------------------

let status = {
    fill: "green",
    shape: "dot",
    text: "Fronius regelt selbst"
};

if (sim) {
    status = {
        fill: "grey",
        shape: "ring",
        text: "SIM | kein Write"
    };
}
else if (externalDischargeLock) {
    status = {
        fill: "red",
        shape: "ring",
        text:
            lockSources.length
                ? "Entladen gesperrt: " + lockSources.join(", ")
                : "Entladen gesperrt | Verto frei"
    };
}
else if (strategicAllowed && totalOutwrte > 0) {
    status = {
        fill: "blue",
        shape: "dot",
        text:
            `Strategisch ${round0(totalDischargeW)} W → ${round1(targetSoc)}%`
    };
}
else if (
    inDischargeWindow &&
    socValid &&
    soc <= targetSoc
) {
    status = {
        fill: "green",
        shape: "dot",
        text:
            `Ziel-SOC ${round1(targetSoc)}% erreicht | Fronius frei`
    };
}
else if (chargeBlockAllowed) {
    status = {
        fill: "yellow",
        shape: "ring",
        text: "Laden gesperrt | Entladen Fronius"
    };
}
else if (chargeLimitActive) {
    status = {
        fill: "yellow",
        shape: "ring",
        text:
            `Laden max. ${round1(maxChargePercent)}% | Entladen Fronius`
    };
}

node.status(status);
return msg;

// ======================================================
// NODE: Modbus_Befehle_bauen V6.2
// Zweck:
// - Liest den aktiven Modbus-Vorschlag aus Strategie_V6_Debug
// - Baut daraus Modbus-Flex-Write Messages
// - Unterstützt 3 Register:
//     1) StorCtl_Mod
//     2) OutWRte
//     3) InWRte
// - Unterstützt jetzt negative InWRte-Werte für erzwungene Entladung
// - Schreibt NICHT selbst, sondern gibt fertige Messages aus
// - Verhindert unnötiges Dauerschreiben
// - Refresh alle 60 Sekunden
//
// FUNKTIONIERENDE ENTLADE-VARIANTE:
//   StorCtl_Mod = 3
//   OutWRte     = +X
//   InWRte      = -X
//
// Beispiel:
//   X = 1000 bedeutet 10 % der Batterieleistung,
//   nicht 1000 W direkt.
// ======================================================


// ======================================================
// 1) MODBUS PARAMETER
// ======================================================

// Verto / Fronius Modbus Unit ID
const UNIT_ID = 1;

// ------------------------------------------------------
// Getestete Node-RED-Adressen
// ------------------------------------------------------
//
// StorCtl_Mod:
//   Node-RED-Adresse: 40368
//
// OutWRte:
//   Node-RED-Adresse: 40375
//
// InWRte:
//   Node-RED-Adresse: 40376
// ------------------------------------------------------

const REG_STORCTL_MOD = 40368;
const REG_OUTWRTE     = 40375;
const REG_INWRTE      = 40376;

// FC6 = Write Single Holding Register
const FC_WRITE_SINGLE = 6;

// Bei gleichem Sollwert trotzdem alle 60 Sekunden refreshen
const REFRESH_MS = 60_000;

// Sicherheitsgrenzen für WRte-Werte
// -10000 = -100 %
// 0      = 0 %
// 10000  = 100 %
const WRTE_MIN_SIGNED = -10000;
const WRTE_MAX_SIGNED =  10000;

const WRTE_MIN_POSITIVE = 0;
const WRTE_MAX_POSITIVE = 10000;


// ======================================================
// 2) INPUT ROBUST EINLESEN
// ======================================================

// Unterstützte Eingänge:
// - msg.control
// - msg.payload.control
// - msg.payload.modbus_proposal

const proposal =
    msg.control ??
    msg.payload?.control ??
    msg.payload?.modbus_proposal;

if (!proposal) {
    msg.payload = {
        error: true,
        reason: "Weder msg.control noch msg.payload.modbus_proposal vorhanden",
        available_payload_keys: Object.keys(msg.payload || {}),
        ts: new Date().toISOString()
    };

    node.status({
        fill: "red",
        shape: "ring",
        text: "keine Modbus-Proposal-Daten"
    });

    return [null, msg];
}


// ======================================================
// 3) FELDER AUS STRATEGIE LESEN
// ======================================================

const writeActive = proposal.write_active === true;

const storctlModRaw =
    proposal.storctl_mod ??
    proposal.storage_control_mode ??
    proposal.storageControlMode;

const outwrteRaw =
    proposal.outwrte ??
    proposal.outwrte_w ??
    proposal.outwrte_value ??
    0;

// Wichtig:
// null bedeutet: InWRte NICHT schreiben.
// Zahl bedeutet: InWRte ausdrücklich schreiben.
// Negative Werte sind jetzt erlaubt und wichtig.
// Beispiel:
//   inwrte = -1000 erzwingt gemeinsam mit mode=3 und outwrte=1000 Entladung.
const inwrteRaw =
    proposal.inwrte ??
    null;


// ======================================================
// 4) WENN STRATEGIE NICHT SCHREIBEN WILL
// ======================================================

if (!writeActive) {
    msg.payload = {
        skipped: true,
        reason: "Strategie meldet write_active=false - kein Modbus Write",

        proposal: {
            storctl_mod: storctlModRaw,
            outwrte: outwrteRaw,
            inwrte: inwrteRaw,
            note: proposal.note ?? null,
            safety: proposal.safety ?? null
        },

        ts: new Date().toISOString()
    };

    node.status({
        fill: "grey",
        shape: "ring",
        text: "write_active=false"
    });

    return [null, msg];
}


// ======================================================
// 5) PFLICHTWERTE PRÜFEN
// ======================================================

if (typeof storctlModRaw !== "number" || !Number.isFinite(storctlModRaw)) {
    msg.payload = {
        error: true,
        reason: "storctl_mod fehlt oder ist keine gültige Zahl",
        received_proposal: proposal,
        ts: new Date().toISOString()
    };

    node.status({
        fill: "red",
        shape: "ring",
        text: "storctl_mod ungültig"
    });

    return [null, msg];
}

if (typeof outwrteRaw !== "number" || !Number.isFinite(outwrteRaw)) {
    msg.payload = {
        error: true,
        reason: "outwrte fehlt oder ist keine gültige Zahl",
        received_proposal: proposal,
        ts: new Date().toISOString()
    };

    node.status({
        fill: "red",
        shape: "ring",
        text: "outwrte ungültig"
    });

    return [null, msg];
}

if (
    inwrteRaw !== null &&
    (typeof inwrteRaw !== "number" || !Number.isFinite(inwrteRaw))
) {
    msg.payload = {
        error: true,
        reason: "inwrte ist nicht null, aber auch keine gültige Zahl",
        received_proposal: proposal,
        ts: new Date().toISOString()
    };

    node.status({
        fill: "red",
        shape: "ring",
        text: "inwrte ungültig"
    });

    return [null, msg];
}


// ======================================================
// 6) WERTE NORMALISIEREN
// ======================================================

// StorCtl_Mod:
// 0 = externe Steuerung aus
// 1 = Ladelimit aktiv
// 2 = Entladelimit aktiv
// 3 = Lade- und Entladelimit aktiv
const mode = Math.trunc(storctlModRaw);

// Sicherheit: nur 0..3 erlauben
if (mode < 0 || mode > 3) {
    msg.payload = {
        error: true,
        reason: "storctl_mod außerhalb erlaubtem Bereich 0..3",
        mode,
        received_proposal: proposal,
        ts: new Date().toISOString()
    };

    node.status({
        fill: "red",
        shape: "ring",
        text: "storctl_mod außerhalb 0..3"
    });

    return [null, msg];
}

// ------------------------------------------------------
// OutWRte:
// Immer positiv 0..10000.
// ------------------------------------------------------
let outwrte = Math.round(Math.abs(outwrteRaw));
outwrte = Math.max(WRTE_MIN_POSITIVE, Math.min(outwrte, WRTE_MAX_POSITIVE));

// ------------------------------------------------------
// InWRte:
// Jetzt signed!
// - null bleibt null und wird nicht geschrieben.
// - positive Werte: Ladefreigabe / Ladebegrenzung
// - negative Werte: für erzwungene Entladung relevant
// ------------------------------------------------------
let inwrte = null;

if (inwrteRaw !== null) {
    inwrte = Math.round(Number(inwrteRaw));
    inwrte = Math.max(WRTE_MIN_SIGNED, Math.min(inwrte, WRTE_MAX_SIGNED));
}

// ------------------------------------------------------
// Sauberer Freigabezustand:
// Wenn mode=0, externe Steuerung aus.
// Dann schreiben wir bewusst OutWRte=10000 und InWRte=10000,
// damit keine alten Begrenzungen im Register stehen bleiben.
// ------------------------------------------------------
if (mode === 0) {
    outwrte = 10000;
    inwrte = 10000;
}


// ======================================================
// 7) SIGNED INT16 -> RAW UINT16
// ======================================================
//
// Modbus-Register schreibt rohe 16 Bit.
// Negative int16-Werte müssen als uint16 übertragen werden.
//
// Beispiele:
//   -1000 -> 65536 - 1000 = 64536
//   -5000 -> 65536 - 5000 = 60536
//
// Positive Werte bleiben gleich.
// ======================================================

function signedToUint16(value) {
    const n = Math.round(Number(value));

    if (!Number.isFinite(n)) {
        return 0;
    }

    if (n < 0) {
        return 65536 + n;
    }

    return n;
}


// ======================================================
// 8) WRITE-GUARD
// ======================================================
//
// Zweck:
// - Nicht alle 5 Sekunden blind schreiben
// - Nur schreiben, wenn sich mode, outwrte oder inwrte ändern
// - Oder spätestens alle 60 Sekunden refreshen
//
// Wichtig:
// inwrte=null, inwrte=0 und inwrte=-1000 sind verschieden.
// null  = Register nicht schreiben
// 0     = Register aktiv auf 0 schreiben
// -1000 = signed Vorgabe, raw als 64536 schreiben
// ======================================================

const now = Date.now();

const last = flow.get("$parent.v6.modbus.last_write") || {
    mode: null,
    outwrte: null,
    inwrte: "__unset__",
    ts: 0
};

const changed =
    last.mode !== mode ||
    last.outwrte !== outwrte ||
    last.inwrte !== inwrte;

const refreshDue =
    now - (last.ts || 0) >= REFRESH_MS;

if (!changed && !refreshDue) {
    msg.payload = {
        skipped: true,
        reason: "Sollwerte unverändert, Refresh noch nicht fällig",

        values: {
            mode,
            storctl_mod: mode,
            outwrte,
            inwrte
        },

        raw_values: {
            outwrte_raw_uint16: signedToUint16(outwrte),
            inwrte_raw_uint16: inwrte === null ? null : signedToUint16(inwrte)
        },

        age_ms: now - last.ts,
        next_refresh_in_ms: Math.max(0, REFRESH_MS - (now - last.ts)),
        ts: new Date().toISOString()
    };

    node.status({
        fill: "grey",
        shape: "ring",
        text: `skip | M=${mode} O=${outwrte} I=${inwrte}`
    });

    return [null, msg];
}


// ======================================================
// 9) MODBUS WRITE MESSAGE HILFSFUNKTION
// ======================================================

function buildWriteMsg(name, address, signedValue) {
    const rawValue = signedToUint16(signedValue);

    return {
        topic: `write_${name}`,

        payload: {
            value: [rawValue],
            fc: FC_WRITE_SINGLE,
            unitid: UNIT_ID,
            address: address,
            quantity: 1
        },

        modbus_write: {
            name,
            address,
            signed_value: signedValue,
            raw_uint16_value: rawValue,
            fc: FC_WRITE_SINGLE,
            unitid: UNIT_ID
        },

        original_strategy: msg.payload
    };
}


// ======================================================
// 10) MODBUS WRITE MESSAGES BAUEN
// ======================================================
//
// Reihenfolge:
//
// Wenn mode = 0:
//   1. StorCtl_Mod zuerst auf 0
//   2. OutWRte auf 10000
//   3. InWRte auf 10000
//
// Wenn mode > 0:
//   1. OutWRte schreiben
//   2. InWRte schreiben, falls inwrte !== null
//   3. StorCtl_Mod zuletzt schreiben
//
// Grund:
// - Beim Aktivieren zuerst Grenzwerte setzen, dann Modus aktivieren.
// - Beim Freigeben zuerst Modus ausschalten.
// ======================================================

const writeMessages = [];

if (mode === 0) {
    writeMessages.push(
        buildWriteMsg("storctl_mod", REG_STORCTL_MOD, mode)
    );

    writeMessages.push(
        buildWriteMsg("outwrte", REG_OUTWRTE, outwrte)
    );

    writeMessages.push(
        buildWriteMsg("inwrte", REG_INWRTE, inwrte)
    );
} else {
    writeMessages.push(
        buildWriteMsg("outwrte", REG_OUTWRTE, outwrte)
    );

    if (inwrte !== null) {
        writeMessages.push(
            buildWriteMsg("inwrte", REG_INWRTE, inwrte)
        );
    }

    writeMessages.push(
        buildWriteMsg("storctl_mod", REG_STORCTL_MOD, mode)
    );
}


// ======================================================
// 11) STATE SPEICHERN
// ======================================================

flow.set("$parent.v6.modbus.last_write", {
    mode,
    outwrte,
    inwrte,
    ts: now,
    iso: new Date().toISOString()
});


// ======================================================
// 12) DEBUG MESSAGE
// ======================================================

const debugMsg = {
    topic: "v6_modbus_write_debug",

    payload: {
        write: changed ? "changed" : "refresh",

        values: {
            mode,
            storctl_mod: mode,
            outwrte,
            inwrte
        },

        raw_values: {
            outwrte_raw_uint16: signedToUint16(outwrte),
            inwrte_raw_uint16: inwrte === null ? null : signedToUint16(inwrte)
        },

        interpretation: {
            mode_text:
                mode === 0 ? "externe Speichersteuerung aus" :
                mode === 1 ? "Ladelimit aktiv" :
                mode === 2 ? "Entladelimit aktiv" :
                mode === 3 ? "Lade- und Entladelimit aktiv" :
                "unbekannt",

            force_discharge_active:
                mode === 3 &&
                typeof inwrte === "number" &&
                inwrte < 0 &&
                outwrte > 0,

            note:
                mode === 3 && inwrte < 0
                    ? "Funktionierende Entladevariante: OutWRte positiv, InWRte negativ"
                    : null
        },

        registers: {
            storctl_mod_address: REG_STORCTL_MOD,
            outwrte_address: REG_OUTWRTE,
            inwrte_address: REG_INWRTE,
            fc: FC_WRITE_SINGLE,
            unitid: UNIT_ID
        },

        messages_built: writeMessages.map(m => ({
            topic: m.topic,
            address: m.payload.address,
            signed_value: m.modbus_write.signed_value,
            raw_uint16_value: m.payload.value[0],
            fc: m.payload.fc,
            unitid: m.payload.unitid
        })),

        proposal_note: proposal.note ?? null,
        proposal_safety: proposal.safety ?? null,

        ts: new Date().toISOString()
    }
};


// ======================================================
// 13) NODE STATUS
// ======================================================

let statusText = `M=${mode} O=${outwrte} I=${inwrte}`;

if (mode === 0) {
    statusText = `FREI | ${statusText}`;
} else if (mode === 3 && inwrte < 0 && outwrte > 0) {
    statusText = `FORCE DISCHARGE | ${statusText}`;
} else if (mode === 3) {
    statusText = `MODE 3 | ${statusText}`;
} else if (mode === 2) {
    statusText = `MODE 2 | ${statusText}`;
}

node.status({
    fill: mode === 0 ? "green" : "yellow",
    shape: "dot",
    text: statusText
});


// ======================================================
// 14) OUTPUT
// ======================================================
//
// Ausgang 1:
// - echte Modbus-Flex-Write Messages
//
// Ausgang 2:
// - Debug / Zusammenfassung
// ======================================================

return [
    writeMessages,
    debugMsg
];

// ======================================================
// NODE: Readback_Befehle_bauen
// Zweck:
// - Baut Modbus-Flex-Getter Requests
// - Liest die aktuellen Verto-Register zurück
// - Register:
//     1) StorCtl_Mod
//     2) OutWRte
//     3) InWRte
// ======================================================


// ======================================================
// 1) MODBUS PARAMETER
// ======================================================

const UNIT_ID = 1;

// Getestete Node-RED-Adressen aus V5
const REG_STORCTL_MOD = 40368;
const REG_OUTWRTE     = 40375;
const REG_INWRTE      = 40376;

// FC3 = Read Holding Register
const FC_READ_HOLDING = 3;


// ======================================================
// 2) READ REQUESTS BAUEN
// ======================================================

const readOutwrte = {
    topic: "read_outwrte",
    payload: {
        fc: FC_READ_HOLDING,
        unitid: UNIT_ID,
        address: REG_OUTWRTE,
        quantity: 1
    }
};

const readStorctlMod = {
    topic: "read_storctl_mod",
    payload: {
        fc: FC_READ_HOLDING,
        unitid: UNIT_ID,
        address: REG_STORCTL_MOD,
        quantity: 1
    }
};

const readInwrte = {
    topic: "read_inwrte",
    payload: {
        fc: FC_READ_HOLDING,
        unitid: UNIT_ID,
        address: REG_INWRTE,
        quantity: 1
    }
};


// ======================================================
// 3) STATUS AM NODE
// ======================================================

node.status({
    fill: "blue",
    shape: "dot",
    text: "Readback Requests: O/M/I"
});


// ======================================================
// 4) OUTPUT
// ======================================================

return [[
    readOutwrte,
    readStorctlMod,
    readInwrte
]];

// ======================================================
// NODE: Readback_Status
// Zweck:
// - Formatiert Modbus-Readback vom Verto
// - Speichert Istwerte in flow
// - Zeigt Live-Status schön lesbar direkt im Node-RED-Flow
//
// Anzeige-Beispiele:
//   ✅ Frei | Entl. 0% | Laden roh -6000 | 0s
//   🔵 Entladen | Entl. 24% | Laden frei | 1s
//   🟡 Ladeblock | Entl. 0% | Laden 0% | 0s
//
// Bedeutung:
//   M = StorCtl_Mod
//   O = OutWRte
//   I = InWRte
// ======================================================


// ======================================================
// 1) HILFSFUNKTIONEN
// ======================================================

function extractRegisterValue(payload, msg) {
    // Häufig bei node-red-contrib-modbus:
    // msg.payload.data = [wert]
    if (Array.isArray(payload?.data)) {
        return payload.data[0];
    }

    // Manche Antworten haben msg.responseBuffer.data
    if (Array.isArray(msg?.responseBuffer?.data)) {
        return msg.responseBuffer.data[0];
    }

    // Manche Antworten haben payload.responseBuffer.data
    if (Array.isArray(payload?.responseBuffer?.data)) {
        return payload.responseBuffer.data[0];
    }

    // Direktes Array
    if (Array.isArray(payload)) {
        return payload[0];
    }

    // Buffer-Array
    if (Array.isArray(payload?.buffer)) {
        return payload.buffer[0];
    }

    // Fallback
    return payload;
}

function asNumberOrNull(value) {
    const n = Number(value);
    return Number.isFinite(n) ? n : null;
}

// Wandelt 16-bit unsigned Rohwert in signed INT16 um.
// Beispiel:
// 59536 → -6000
function uint16ToInt16(value) {
    if (value === null || value === undefined) return null;

    const n = Number(value);
    if (!Number.isFinite(n)) return null;

    return n > 32767 ? n - 65536 : n;
}

// Fronius WRte:
// 0     = 0 %
// 10000 = 100 %
function wrteToPercent(value) {
    if (value === null || value === undefined) return null;

    const n = Number(value);
    if (!Number.isFinite(n)) return null;

    return Math.round((n / 10000) * 100);
}

function textOrQuestion(value) {
    return value === null || value === undefined ? "?" : String(value);
}

function percentTextFromWrte(value) {
    const p = wrteToPercent(value);
    return p === null ? "?" : `${p}%`;
}


// ======================================================
// 2) WERT AUS MODBUS-ANTWORT LESEN
// ======================================================

const rawValue = extractRegisterValue(msg.payload, msg);
const rawNumber = asNumberOrNull(rawValue);
const signedValue = uint16ToInt16(rawNumber);


// ======================================================
// 3) JE NACH TOPIC IM FLOW SPEICHERN
// ======================================================

if (msg.topic === "read_storctl_mod") {
    // StorCtl_Mod ist normal unsigned 0..3
    flow.set("$parent.readback.storctl_mod_raw", rawNumber);
    flow.set("$parent.readback.storctl_mod", rawNumber);
    flow.set("$parent.readback.storctl_mod_ts", Date.now());
}

else if (msg.topic === "read_outwrte") {
    // OutWRte ist 0..10000
    flow.set("$parent.readback.outwrte_raw", rawNumber);
    flow.set("$parent.readback.outwrte_signed", signedValue);
    flow.set("$parent.readback.outwrte", rawNumber);
    flow.set("$parent.readback.outwrte_ts", Date.now());
}

else if (msg.topic === "read_inwrte") {
    // InWRte kann als signed INT16 zurückkommen.
    // Beispiel 59536 raw = -6000 signed.
    flow.set("$parent.readback.inwrte_raw", rawNumber);
    flow.set("$parent.readback.inwrte_signed", signedValue);
    flow.set("$parent.readback.inwrte", signedValue);
    flow.set("$parent.readback.inwrte_ts", Date.now());
}

else {
    node.warn(`Unbekanntes Readback-Topic: ${msg.topic}`);
}


// ======================================================
// 4) AKTUELLE ISTWERTE AUS FLOW HOLEN
// ======================================================

const storctlMod = flow.get("$parent.readback.storctl_mod");
const outwrte    = flow.get("$parent.readback.outwrte");
const inwrte     = flow.get("$parent.readback.inwrte");

const storctlRaw = flow.get("$parent.readback.storctl_mod_raw");
const outwrteRaw = flow.get("$parent.readback.outwrte_raw");
const inwrteRaw  = flow.get("$parent.readback.inwrte_raw");

const storctlTs = flow.get("$parent.readback.storctl_mod_ts") ?? 0;
const outwrteTs = flow.get("$parent.readback.outwrte_ts") ?? 0;
const inwrteTs  = flow.get("$parent.readback.inwrte_ts") ?? 0;


// ======================================================
// 5) MODUS TEXT UND FARBE
// ======================================================

let fill = "grey";
let shape = "ring";
let modeText = "❔ Unbekannt";

if (storctlMod === 0) {
    fill = "green";
    shape = "dot";
    modeText = "✅ Frei";
} else if (storctlMod === 1) {
    fill = "yellow";
    shape = "dot";
    modeText = "🟡 Ladeblock";
} else if (storctlMod === 2) {
    fill = "blue";
    shape = "dot";
    modeText = "🔵 Entladen";
} else if (storctlMod === 3) {
    fill = "purple";
    shape = "dot";
    modeText = "🟣 Entl.+Ladeblock";
}


// ======================================================
// 6) ANZEIGETEXTE FÜR OUTWRTE UND INWRTE
// ======================================================

const outwrteText =
    outwrte === null || outwrte === undefined
        ? "Entl. ?"
        : `Entl. ${percentTextFromWrte(outwrte)}`;

// InWRte ist etwas tricky:
// - Bei Modus 0 ist es nicht aktiv und kann alte/komische Werte enthalten.
// - Bei Modus 1 oder 3 ist InWRte relevant.
// - Rohwert 59536 kann signed -6000 bedeuten.
let inwrteText = "Laden ?";

if (inwrte === null || inwrte === undefined) {
    inwrteText = "Laden ?";
} else if (storctlMod === 0 || storctlMod === 2) {
    // In diesen Modi ist InWRte nicht aktiv.
    // Trotzdem zeigen wir Diagnose, wenn ein auffälliger raw/signed Wert vorhanden ist.
    if (inwrteRaw !== null && inwrteRaw !== undefined && inwrteRaw > 32767) {
        inwrteText = `Laden frei`;
    } else {
        inwrteText = "Laden frei";
    }
} else {
    // Modus 1 oder 3: InWRte ist aktiv relevant.
    if (inwrte === 0) {
        inwrteText = "Laden 0%";
    } else if (inwrte > 0) {
        inwrteText = `Laden ${percentTextFromWrte(inwrte)}`;
    } else {
        // negativer signed-Wert: Diagnose statt Prozent
        inwrteText = `Laden roh ${inwrte}`;
    }
}


// ======================================================
// 7) ALTER DER WERTE
// ======================================================

const newestTs = Math.max(storctlTs, outwrteTs, inwrteTs);

const ageSec =
    newestTs > 0
        ? Math.round((Date.now() - newestTs) / 1000)
        : null;

const ageText =
    ageSec === null
        ? "?s"
        : `${ageSec}s`;


// ======================================================
// 8) KOMPAKTER NODE-STATUS
// ======================================================

const statusText =
    `${modeText} | ${outwrteText} | ${inwrteText} | ${ageText}`;

node.status({
    fill,
    shape,
    text: statusText
});


// ======================================================
// 9) DEBUG-PAYLOAD AUSGEBEN
// ======================================================

msg.payload = {
    topic: msg.topic,

    last_register: {
        topic: msg.topic,
        raw: rawNumber,
        signed_int16: signedValue
    },

    readback: {
        storctl_mod: storctlMod ?? null,
        outwrte: outwrte ?? null,
        inwrte: inwrte ?? null
    },

    raw: {
        storctl_mod_raw: storctlRaw ?? null,
        outwrte_raw: outwrteRaw ?? null,
        inwrte_raw: inwrteRaw ?? null
    },

    percent: {
        outwrte_percent: wrteToPercent(outwrte),
        inwrte_percent:
            inwrte !== null &&
            inwrte !== undefined &&
            inwrte >= 0
                ? wrteToPercent(inwrte)
                : null
    },

    status: {
        text: statusText,
        fill,
        shape,
        mode_text: modeText,
        outwrte_text: outwrteText,
        inwrte_text: inwrteText,
        age_sec: ageSec
    },

    timestamps: {
        storctl_mod_ts: storctlTs,
        outwrte_ts: outwrteTs,
        inwrte_ts: inwrteTs,
        newest_age_sec: ageSec
    },

    ts: new Date().toISOString()
};

return msg;

// ======================================================
// NODE: Heubelüftung abfragen
// Zweck:
// - JSON-Status vom Shelly-Skript auswerten
// - Haken "Automatik AKTIV" abfragen
// - Daraus einen allgemeinen Eingang "Entladen Sperren" erzeugen
//
// Erwarteter Shelly-Status:
// {
//   "timer_active": true/false,
//   "switch_output": true/false,
//   "source": "shelly_heubelueftung"
// }
//
// Logik:
// timer_active = true  -> Entladen sperren
// timer_active = false -> Entladen freigeben
// ======================================================

let p = msg.payload;

// Falls HTTP Request / JSON Node doch einen String liefert
if (typeof p === "string") {
    try {
        p = JSON.parse(p);
    } catch (e) {
        node.error("Shelly JSON konnte nicht gelesen werden", msg);

        node.status({
            fill: "red",
            shape: "ring",
            text: "JSON Fehler"
        });

        return null;
    }
}

// Sicherheitscheck
if (!p || typeof p !== "object") {
    node.error("Shelly Payload fehlt oder ist kein Objekt", msg);

    node.status({
        fill: "red",
        shape: "ring",
        text: "Payload fehlt"
    });

    return null;
}

// Shelly-Haken auswerten
const timerActive = p.timer_active === true;

// Aktueller Relaiszustand, nur zur Anzeige/Debug
const switchOutput = p.switch_output === true;

// ======================================================
// Deine gewünschte Logik:
// Haken "Automatik AKTIV" gesetzt
// = Heubelüftung hat Vorrang
// = Verto-Entladung sperren
// ======================================================

const entladenSperren = timerActive;

// ======================================================
// Allgemeiner Ausgang für Sammel-Node "Entladen-Sperre sammeln"
// Später können andere Nodes das gleiche Format senden:
// - Wallbox
// - Heizstab
// - großer Verbraucher
// - sonstige Sperrbedingungen
// ======================================================

msg.topic = "entladen_sperre";
msg.lock_source = "shelly_heubelueftung";
msg.entladen_sperren = entladenSperren;

msg.payload = {
    source: "shelly_heubelueftung",

    // Allgemeiner Sperrwert
    entladen_sperren: entladenSperren,

    // Shelly-Rohwerte zur Kontrolle
    shelly_timer_active: timerActive,
    shelly_switch_output: switchOutput,

    // Erklärung für Debug
    reason: entladenSperren
        ? "Shelly Automatik AKTIV -> Entladen sperren"
        : "Shelly Automatik INAKTIV -> Entladen freigeben"
};

// Node-Status
node.status({
    fill: entladenSperren ? "red" : "green",
    shape: entladenSperren ? "ring" : "dot",
    text: entladenSperren
        ? "Entladen gesperrt"
        : "Entladen frei"
});

return msg;

// ======================================================
// NODE: Entladesperren sammeln
// Zweck:
// - Allgemeine Entladesperren mehrerer Quellen sammeln
// - Wenn mindestens eine Quelle aktiv ist:
//   flow.verto_discharge_lock = true
//
// Erwartetes Eingangsformat:
// msg.topic = "entladen_sperre"
// msg.lock_source = "shelly_heubelueftung"
// msg.entladen_sperren = true/false
//
// Oder alternativ:
// msg.payload.entladen_sperren = true/false
// msg.payload.source = "shelly_heubelueftung"
// ======================================================

// Nur Nachrichten für die Entladesperre verarbeiten
if (msg.topic !== "entladen_sperre") {
    node.status({
        fill: "grey",
        shape: "ring",
        text: "ignoriert: falsches topic"
    });
    return null;
}

// Quelle bestimmen
const source =
    msg.lock_source ||
    msg.payload?.source ||
    "unknown_source";

// Sperrwert auswerten
const active =
    msg.entladen_sperren === true ||
    msg.payload?.entladen_sperren === true;

// Bestehende Sperren laden
let locks = flow.get("verto_discharge_locks") || {};

// Diese Quelle aktualisieren
locks[source] = {
    active: active,
    updated: Date.now(),
    reason: msg.payload?.reason || "",
    last_payload: msg.payload || null
};

// Sperren speichern
flow.set("verto_discharge_locks", locks);

// Gesamtstatus berechnen
// Sobald mindestens eine Quelle aktiv ist, ist Entladen gesperrt.
let anyActive = false;
let activeSources = [];

for (let key in locks) {
    if (locks[key] && locks[key].active === true) {
        anyActive = true;
        activeSources.push(key);
    }
}

// Gesamtstatus im Flow speichern
flow.set("verto_discharge_lock", anyActive);
flow.set("verto_discharge_lock_sources", activeSources);
flow.set("verto_discharge_lock_updated", Date.now());

// Ausgabe für Debug / weitere Anzeige
msg.payload = {
    entladen_sperren: anyActive,
    active_sources: activeSources,
    all_locks: locks,
    reason: anyActive
        ? "Entladen gesperrt durch: " + activeSources.join(", ")
        : "Keine aktive Entladesperre"
};

// Node Status
node.status({
    fill: anyActive ? "red" : "green",
    shape: anyActive ? "ring" : "dot",
    text: anyActive
        ? "GESPERRT: " + activeSources.join(", ")
        : "Entladen frei"
});

return msg;

// ======================================================
// NODE: Forecast speichern GUI
// Zweck:
// - Nimmt bevorzugt den bereits ausgewerteten Forecast_V6 Output
// - Fallback: kann weiterhin rohe watt_hours_period Daten auswerten
// - Speichert forecast_today_kwh und forecast_tomorrow_kwh für das GUI
// ======================================================

function localDateKey(date) {
    return new Intl.DateTimeFormat("sv-SE", {
        timeZone: "Europe/Vienna",
        year: "numeric",
        month: "2-digit",
        day: "2-digit"
    }).format(date);
}

function addDays(date, days) {
    const d = new Date(date);
    d.setDate(d.getDate() + days);
    return d;
}

function num(...values) {
    for (const v of values) {
        const n = Number(v);
        if (Number.isFinite(n)) return n;
    }
    return null;
}

function dateFromKey(key) {
    if (!key) return null;

    const s = String(key);

    const m = s.match(/^(\d{4}-\d{2}-\d{2})/);
    if (m) return m[1];

    const d = new Date(s);
    if (!isNaN(d.getTime())) return localDateKey(d);

    return null;
}

const p = msg.payload || {};

const todayKey = localDateKey(new Date());
const tomorrowKey = localDateKey(addDays(new Date(), 1));

let todayKwh = null;
let tomorrowKwh = null;
let todayDate = todayKey;
let tomorrowDate = tomorrowKey;
let dailyKwh = {};


// ======================================================
// 1) BEVORZUGT: Forecast_V6 liefert bereits fertige Werte
// ======================================================

todayKwh = num(
    p.forecast?.today?.kwh,
    p.today?.kwh,
    p.forecast_today_kwh,
    p.today_kwh,
    p.kwh
);

tomorrowKwh = num(
    p.forecast?.tomorrow?.kwh,
    p.tomorrow?.kwh,
    p.forecast_tomorrow_kwh,
    p.tomorrow_kwh
);

todayDate =
    p.forecast?.today?.date ??
    p.today?.date ??
    p.today_date ??
    todayKey;

tomorrowDate =
    p.forecast?.tomorrow?.date ??
    p.tomorrow?.date ??
    p.tomorrow_date ??
    tomorrowKey;

if (todayKwh !== null) {
    dailyKwh[todayDate] = todayKwh;
}

if (tomorrowKwh !== null) {
    dailyKwh[tomorrowDate] = tomorrowKwh;
}


// ======================================================
// 2) FALLBACK: Rohe watt_hours_period Daten auswerten
//    Nur wenn oben keine fertigen Werte gefunden wurden
// ======================================================

if (todayKwh === null && tomorrowKwh === null) {
    const period =
        p.result?.watt_hours_period ??
        p.watt_hours_period ??
        p.result?.watthours_period ??
        null;

    const sumsWh = {};

    if (period && typeof period === "object") {
        if (Array.isArray(period)) {
            for (const row of period) {
                let time;
                let wh;

                if (Array.isArray(row)) {
                    time = row[0];
                    wh = Number(row[1]);
                } else if (row && typeof row === "object") {
                    time =
                        row.time ??
                        row.timestamp ??
                        row.datetime ??
                        row.period_end ??
                        row.period;

                    wh = Number(
                        row.watt_hours ??
                        row.wh ??
                        row.value ??
                        row.watt_hours_period
                    );
                }

                const day = dateFromKey(time);

                if (day && Number.isFinite(wh)) {
                    sumsWh[day] = (sumsWh[day] || 0) + wh;
                }
            }
        } else {
            for (const [key, value] of Object.entries(period)) {
                const day = dateFromKey(key);
                const wh = Number(value);

                if (day && Number.isFinite(wh)) {
                    sumsWh[day] = (sumsWh[day] || 0) + wh;
                }
            }
        }
    }

    dailyKwh = Object.fromEntries(
        Object.entries(sumsWh).map(([k, v]) => [k, v / 1000])
    );

    todayKwh = dailyKwh[todayKey] ?? 0;
    tomorrowKwh = dailyKwh[tomorrowKey] ?? 0;
    todayDate = todayKey;
    tomorrowDate = tomorrowKey;
}


// ======================================================
// 3) Finale Werte speichern
// ======================================================

const forecast = {
    updated_at: new Date().toISOString(),

    today_date: todayDate,
    tomorrow_date: tomorrowDate,

    forecast_today_kwh: todayKwh ?? 0,
    forecast_tomorrow_kwh: tomorrowKwh ?? 0,

    daily_kwh: dailyKwh,

    source: p.source ?? "unknown",
    used_fallback: !!p.used_fallback
};

flow.set("$parent.verto_gui_forecast", forecast);

node.status({
    fill: "blue",
    shape: "dot",
    text: `Heute ${forecast.forecast_today_kwh.toFixed(1)} kWh | Morgen ${forecast.forecast_tomorrow_kwh.toFixed(1)} kWh`
});

msg.payload = forecast;
return msg;

/// ======================================================
// NODE: GUI Livewerte speichern V7.4
//
// Zweck:
// - Livewerte für das Dashboard zwischenspeichern
// - robust gegen unterschiedliche Feldnamen / Verschachtelung
// - bestehende gültige Werte nicht mit null überschreiben
// ======================================================

const FIELD_ALIASES = {
    soc_percent: [
        "soc_percent", "battery_soc", "soc"
    ],
    house_load_w: [
        "house_load_w", "house_load", "load_power_w", "load_w",
        "verbrauch_w", "hausverbrauch_w"
    ],
    pv_power_w: [
        "pv_power_w", "pv_power", "solar_power_w", "solar_power",
        "p_pv", "pac", "pvpower"
    ],
    grid_power_w: [
        "grid_power_w", "grid_power", "netz_w", "netzbezug_w",
        "p_grid", "grid_w"
    ],
    battery_power_w: [
        "battery_power_w", "battery_power", "batterie_w",
        "p_battery"
    ]
};

const aliasSets = Object.fromEntries(
    Object.entries(FIELD_ALIASES).map(([name, aliases]) => [
        name,
        new Set(aliases.map(v => v.toLowerCase()))
    ])
);

function findNumber(obj, aliases, depth = 0) {
    if (!obj || typeof obj !== "object" || depth > 5) return null;

    for (const [key, value] of Object.entries(obj)) {
        if (!aliases.has(String(key).toLowerCase())) continue;

        const n = Number(value);
        if (Number.isFinite(n)) return n;
    }

    for (const value of Object.values(obj)) {
        if (value && typeof value === "object") {
            const found = findNumber(value, aliases, depth + 1);
            if (found !== null) return found;
        }
    }

    return null;
}

const root = {
    ...msg,
    payload: msg.payload
};

const update = {
    updated_at: new Date().toISOString()
};

for (const [field, aliases] of Object.entries(aliasSets)) {
    const value = findNumber(root, aliases);
    if (value !== null) update[field] = value;
}

const live = {
    ...(flow.get("$parent.verto_gui_live") || {}),
    ...update
};

flow.set("$parent.verto_gui_live", live);

node.status({
    fill: "green",
    shape: "dot",
    text: `SOC ${live.soc_percent ?? "?"}% | Haus ${live.house_load_w ?? "?"} W`
});

msg.payload = live;
return msg;

// ======================================================
// NODE: GUI Status bauen V7.4
//
// Aufgabe:
// - KEINE Strategielogik
// - nur Strategie_V7.4 + gespeicherte Livewerte für die GUI
//   in ein kompaktes Dashboard-Payload umformen
// ======================================================

function num(...values) {
    for (const value of values) {
        if (value === null || value === undefined || value === "") continue;

        const n = Number(value);
        if (Number.isFinite(n)) return n;
    }

    return null;
}

function text(...values) {
    for (const value of values) {
        if (
            value !== undefined &&
            value !== null &&
            String(value).trim() !== ""
        ) {
            return String(value);
        }
    }

    return null;
}

function prettyClass(value) {
    const map = {
        VERY_BAD: "SEHR SCHLECHT",
        WEAK: "SCHWACH",
        MEDIUM: "MITTEL",
        GOOD: "GUT",
        VERY_GOOD: "SEHR GUT",
        OFF: "AUS",
        UNKNOWN: "—"
    };

    const key = String(value || "").toUpperCase();
    return map[key] || key || "—";
}

function prettyReason(raw) {
    const r = String(raw || "").trim();

    const map = {
        dynamic_discharge_to_target_by_discharge_end:
            "Strategische Entladung aktiv. Der Ziel-SOC soll bis zum Entladeende erreicht werden.",

        target_soc_reached_stop_discharge:
            "Ziel-SOC erreicht. Die strategische Entladung ist beendet.",

        outside_discharge_window:
            "Außerhalb des strategischen Entladefensters.",

        strategic_discharge_disabled:
            "Strategische Morgenentladung ist deaktiviert.",

        forecast_invalid_no_strategic_discharge:
            "Keine gültige Prognose für heute und morgen. Keine strategische Entladung.",

        soc_missing_no_strategic_discharge:
            "Kein gültiger Batterie-SOC. Keine strategische Entladung.",

        sunrise_charge_block_active:
            "Aufladen ist im Morgenfenster blockiert. Entladen regelt Fronius.",

        outside_charge_block_window:
            "Außerhalb des Ladeblock-Zeitfensters.",

        charge_block_disabled:
