function isObject(value) {
    return value !== null &&
        typeof value === "object" &&
        !Array.isArray(value);
}

function clone(value) {
    return JSON.parse(JSON.stringify(value));
}

function finite(value) {
    const n = Number(value);
    return Number.isFinite(n) ? n : null;
}

// Übernimmt ausschließlich Felder, die im aktuellen Schema existieren.
// Alte / unbekannte Felder verschwinden dadurch automatisch.
function mergeSchema(defaults, existing) {
    if (!isObject(defaults)) {
        return existing !== undefined ? existing : defaults;
    }

    const result = {};

    for (const key of Object.keys(defaults)) {
        const d = defaults[key];
        const hasExisting =
            isObject(existing) &&
            Object.prototype.hasOwnProperty.call(existing, key);

        const e = hasExisting ? existing[key] : undefined;

        result[key] = isObject(d)
            ? mergeSchema(d, e)
            : (e !== undefined ? e : d);
    }

    return result;
}

// ------------------------------------------------------
// 1) Quelle wählen: persistent > RAM > Defaults
// ------------------------------------------------------

const persistentConfig = flow.get(CONFIG_KEY, PERSISTENT_STORE);
const memoryConfig = flow.get(CONFIG_KEY);

let sourceName = "defaults";
let old = {};

if (isObject(persistentConfig)) {
    old = clone(persistentConfig);
    sourceName = "persistent";
}
else if (isObject(memoryConfig)) {
    old = clone(memoryConfig);
    sourceName = "memory";
}

// ------------------------------------------------------
// 2) Migration älterer Versionen
// ------------------------------------------------------

if (!isObject(old.discharge)) old.discharge = {};
if (!isObject(old.reserve)) old.reserve = {};
if (!isObject(old.charge_block)) old.charge_block = {};
if (!isObject(old.charge_limit)) old.charge_limit = {};

// Alte V6/V7-Reservebezeichnungen -> aktuelles Schema
if (old.reserve.very_bad_below_kwh === undefined) {
    old.reserve.very_bad_below_kwh =
        finite(old.reserve.tomorrow_bad_below_kwh) ??
        DEFAULT_CONFIG.reserve.very_bad_below_kwh;
}

if (old.reserve.target_soc_very_bad === undefined) {
    old.reserve.target_soc_very_bad =
        finite(old.reserve.target_soc_bad) ??
        DEFAULT_CONFIG.reserve.target_soc_very_bad;
}

if (old.reserve.weak_below_kwh === undefined) {
    old.reserve.weak_below_kwh =
        finite(old.reserve.tomorrow_weak_below_kwh) ??
        DEFAULT_CONFIG.reserve.weak_below_kwh;
}

if (old.reserve.medium_below_kwh === undefined) {
    old.reserve.medium_below_kwh =
        finite(old.reserve.tomorrow_medium_below_kwh) ??
        DEFAULT_CONFIG.reserve.medium_below_kwh;
}

// Alte Hauslast-Konfiguration:
// Nur die tatsächlich noch sinnvolle Regelreserve übernehmen.
if (old.discharge.house_load_margin_w === undefined) {
    old.discharge.house_load_margin_w =
        finite(old.house_load?.export_margin_w) ??
        DEFAULT_CONFIG.discharge.house_load_margin_w;
}

// V7.3-Felder, die V7.4 bewusst nicht mehr verwendet:
// - discharge.soc_margin_percent
// - discharge.fallback_start_min / fallback_end_min
// - charge_block.min_soc_above_target
// - komplette house_load-Sektion außer migriertem Margin
// - alte morgen-/heute-Sonderfelder
// Diese werden durch mergeSchema automatisch verworfen.

// ------------------------------------------------------
// 3) Aktuelles Schema aufbauen
// ------------------------------------------------------

const config = mergeSchema(DEFAULT_CONFIG, old);
config.version = 7.4;

// ------------------------------------------------------
// 4) NUR RAM setzen
// ------------------------------------------------------

flow.set(CONFIG_KEY, config);
flow.set(
    "strategy_v7_config_initialized_at",
    new Date().toISOString()
);

msg.topic = "strategy_v7_config_initialized";
msg.payload = {
    ok: true,
    version: 7.4,
    source: sourceName,
    config_key: CONFIG_KEY,
    config
};

node.status({
    fill: "green",
    shape: "dot",
    text:
        sourceName === "persistent"
            ? "V7.4 Config aus Datei geladen"
            : sourceName === "memory"
                ? "V7.4 Config aus RAM geladen"
                : "V7.4 Defaults geladen"
});

return msg;

