const CONFIG_KEY = "strategy_v7_config";
const PERSISTENT_STORE = "persistent";

const RULES = {
    "location.latitude":                 { type: "number", min: -90,    max: 90 },
    "location.longitude":                { type: "number", min: -180,   max: 180 },

