    "reserve.medium_below_kwh":           { type: "number", min: 0,      max: 500 },
    "reserve.target_soc_medium":          { type: "number", min: 0,      max: 100 },
    "reserve.target_soc_good":            { type: "number", min: 0,      max: 100 },

