    "charge_limit.very_good_today_min_kwh": { type: "number", min: 0,    max: 500 },
    "charge_limit.very_good_percent":     { type: "number", min: 0,      max: 100 },
    "charge_limit.good_today_min_kwh":    { type: "number", min: 0,      max: 500 },
    "charge_limit.good_percent":          { type: "number", min: 0,      max: 100 },
    "charge_limit.medium_today_min_kwh":  { type: "number", min: 0,      max: 500 },
    "charge_limit.medium_percent":        { type: "number", min: 0,      max: 100 },
    "charge_limit.weak_percent":          { type: "number", min: 0,      max: 100 }
};

function clone(value) {
    return JSON.parse(JSON.stringify(value));
}

function getNested(obj, path) {
    let cur = obj;

    for (const key of path.split(".")) {
        if (cur === null || cur === undefined || typeof cur !== "object") {
            return undefined;
        }
        cur = cur[key];
    }

    return cur;
}

function setNested(obj, path, value) {
    const parts = path.split(".");
    let cur = obj;

    for (let i = 0; i < parts.length - 1; i++) {
        const key = parts[i];

        if (!cur[key] || typeof cur[key] !== "object") {
            cur[key] = {};
        }

        cur = cur[key];
    }

    cur[parts[parts.length - 1]] = value;
}

function normalize(path, value) {
    const rule = RULES[path];

    if (value === null || value === undefined || value === "") {
        return {
            ok: false,
            error: `${path} darf nicht leer sein`
        };
    }

    if (rule.type === "number") {
        const n = Number(value);

        if (!Number.isFinite(n)) {
            return {
                ok: false,
                error: `${path} ist keine gültige Zahl`
            };
        }

        if (n < rule.min || n > rule.max) {
            return {
                ok: false,
                error: `${path} muss zwischen ${rule.min} und ${rule.max} liegen`
            };
        }

        return { ok: true, value: n };
    }

    if (rule.type === "boolean") {
        if (value === true || value === false) {
            return { ok: true, value };
        }

        if ([1, "1", "true", "on"].includes(value)) {
            return { ok: true, value: true };
        }

        if ([0, "0", "false", "off"].includes(value)) {
            return { ok: true, value: false };
        }

        return {
            ok: false,
            error: `${path} ist kein gültiger Ein/Aus-Wert`
        };
    }

    return {
        ok: false,
        error: `Unbekannter Datentyp für ${path}`
    };
}

function validate(cfg) {
    const errors = [];

    const r = cfg.reserve;
    const c = cfg.charge_limit;

    if (!(r.very_bad_below_kwh < r.weak_below_kwh &&
          r.weak_below_kwh < r.medium_below_kwh)) {
        errors.push(
            "Reserve: Schwellen müssen aufsteigend sein: " +
            "SEHR SCHLECHT < SCHWACH < MITTEL."
        );
    }

    const targets = [
        ["SEHR SCHLECHT", r.target_soc_very_bad],
        ["SCHWACH",       r.target_soc_weak],
        ["MITTEL",        r.target_soc_medium],
        ["GUT",           r.target_soc_good]
    ];

    for (const [name, soc] of targets) {
        if (soc < r.min_soc_absolute) {
            errors.push(
                `${name} Ziel-SOC (${soc}%) liegt unter ` +
                `dem absoluten Mindest-Ziel-SOC (${r.min_soc_absolute}%).`
            );
        }
    }

    if (!(c.very_good_today_min_kwh >= c.good_today_min_kwh &&
          c.good_today_min_kwh >= c.medium_today_min_kwh)) {
        errors.push(
            "Ladebegrenzung: Schwellen müssen absteigend sein: " +
            "VERY GOOD >= GOOD >= MEDIUM."
        );
    }

    if (cfg.discharge.max_power_w > cfg.battery.power_ref_w) {
        errors.push(
            "Max. strategische Entladeleistung darf nicht größer " +
            "als battery.power_ref_w sein."
        );
    }

    return errors;
}

