}

const incoming = msg.payload;

if (!incoming || typeof incoming !== "object" || Array.isArray(incoming)) {
    msg.payload = {
        ok: false,
        error: "GUI Config muss ein Objekt sein."
    };

    node.status({
        fill: "red",
        shape: "ring",
        text: "GUI Config ungültig"
    });

    return msg;
}

const current =
    flow.get(CONFIG_KEY) ||
    flow.get(CONFIG_KEY, PERSISTENT_STORE);

if (!current || typeof current !== "object") {
    msg.payload = {
        ok: false,
        error: "strategy_v7_config fehlt. Config Init zuerst ausführen."
    };

    node.status({
        fill: "red",
        shape: "ring",
        text: "V7 Config fehlt"
    });

    return msg;
}

// Saubere neue Config nur aus bekannten Feldern aufbauen.
const next = {
    version: 7.4
};

for (const path of Object.keys(RULES)) {
    const rawIncoming = getNested(incoming, path);
    const rawCurrent = getNested(current, path);
    const raw = rawIncoming !== undefined ? rawIncoming : rawCurrent;

    const result = normalize(path, raw);

    if (!result.ok) {
        msg.payload = {
            ok: false,
            error: result.error,
            field: path
        };

        node.status({
            fill: "red",
            shape: "ring",
            text: `Config Fehler: ${path}`
        });

        return msg;
    }

    setNested(next, path, result.value);
}

const errors = validate(next);

if (errors.length) {
    msg.payload = {
        ok: false,
        error: "Konfiguration nicht gespeichert.",
        validation_errors: errors
    };

    node.status({
        fill: "red",
        shape: "ring",
        text: "Config Plausibilitätsfehler"
    });

    return msg;
}

const savedAt = new Date().toISOString();

// Laufende Config
flow.set(CONFIG_KEY, clone(next));

// Dauerhafte Config auf SD
flow.set(CONFIG_KEY, clone(next), PERSISTENT_STORE);

flow.set("strategy_v7_config_changed_at", savedAt);
flow.set(
    "strategy_v7_config_saved_at",
    savedAt,
    PERSISTENT_STORE
);

msg.topic = "strategy_v7_config_updated";
msg.payload = {
    ok: true,
    saved: true,
    persistent: true,
    version: 7.4,
    saved_at: savedAt,
    config: next
};

node.status({
    fill: "green",
    shape: "dot",
    text: "V7.4 dauerhaft gespeichert"
});

return msg;

// ======================================================
// NODE: URL Batteriedaten
// Komponenten-/BMS-Daten des Verto (BYD-Speicher).
// IP aus der Einstellung VERTO_IP (Node "Verto Plus").
// ======================================================

const ip = String(env.get("VERTO_IP") || "").trim();

if (!ip) {
    node.status({ fill: "red", shape: "ring", text: "IP fehlt (Doppelklick auf Verto Plus)" });
    return null;
}

msg.url = "http://" + ip + "/components/readable";
return msg;

const data = msg.payload?.Body?.Data;

if (!data) {
    node.status({
        fill: "red",
        shape: "ring",
        text: "Keine Fronius-Daten"
    });
    return null;
}


// ======================================================
// BYD-Komponente suchen
// ======================================================

let byd = null;

for (const [id, component] of Object.entries(data)) {

    if (
        component?.attributes?.manufacturer === "BYD" ||
        component?.attributes?.model === "HVM+" ||
        id.startsWith("BYD_Storage")
    ) {
        byd = component;
        break;
    }
}


if (!byd || !byd.channels) {

    node.status({
        fill: "red",
        shape: "ring",
        text: "BYD nicht gefunden"
    });

    return null;
}


const c = byd.channels;
const a = byd.attributes || {};


// ======================================================
// Hilfsfunktionen
// ======================================================

function number(v) {

    const n = Number(v);

    return Number.isFinite(n)
        ? n
        : null;
}


function round(v, decimals = 1) {

    if (!Number.isFinite(v)) {
        return null;
    }

    const f = Math.pow(10, decimals);

    return Math.round(v * f) / f;
}


function jouleToKWh(v) {

    const n = number(v);

    if (n === null) {
        return null;
    }

    return n / 3600000;
}


// ======================================================
// Werte lesen
// ======================================================

const soc =
    number(
        c.BAT_VALUE_STATE_OF_CHARGE_RELATIVE_F32
    );

const soh =
    number(
        c.BAT_VALUE_STATE_OF_HEALTH_RELATIVE_U16
    );


const temp =
    number(
        c.BAT_TEMPERATURE_CELL_F64
    );

const tempMin =
    number(
        c.BAT_TEMPERATURE_CELL_MIN_F64
    );

const tempMax =
    number(
        c.BAT_TEMPERATURE_CELL_MAX_F64
    );


const voltage =
    number(
        c.BAT_VOLTAGE_DC_INTERNAL_F64
    );

const current =
    number(
        c.BAT_CURRENT_DC_INTERNAL_F64
    );


const power =
    voltage !== null &&
        current !== null

        ? voltage * current
        : null;


const capacity =
    jouleToKWh(
        c.BAT_ENERGYACTIVE_MAX_CAPACITY_F64
    );


const storedEnergy =
    jouleToKWh(
        c.BAT_ENERGYACTIVE_ESTIMATION_MAX_CAPACITY_F64
    );


const lifetimeCharged =
    jouleToKWh(
        c.BAT_ENERGYACTIVE_LIFETIME_CHARGED_F64
    );


const lifetimeDischarged =
    jouleToKWh(
        c.BAT_ENERGYACTIVE_LIFETIME_DISCHARGED_F64
    );


const maxCharge =
    number(
        c.DCLINK_POWERACTIVE_MAX_F32
    );


const maxDischarge =
    number(
        c.DCLINK_POWERACTIVE_LIMIT_DISCHARGE_F64
    );


// ======================================================
// Betriebszustand
// BYD: negativer Strom = Entladen
// ======================================================

let operation = "Standby";

if (power !== null) {

    if (power < -50) {
        operation = "Entladen";
    }

    else if (power > 50) {
        operation = "Laden";
    }
}


// ======================================================
// GUI Payload
// ======================================================

msg.topic = "battery_data";


msg.payload = {

    model:
        a.model || "BYD",

    serial:
        a.serial || null,

    stacks:
        number(a.numberStacks),


    SOC_pct:
        round(soc, 1),

    SOH_pct:
        round(soh, 0),


    Temperatur_C:
        round(temp, 1),

    Temperatur_Min_C:
        round(tempMin, 1),

    Temperatur_Max_C:
        round(tempMax, 1),

    Temperatur_Delta_K:
        tempMin !== null &&
            tempMax !== null

            ? round(
                tempMax - tempMin,
                1
            )

            : null,


    Spannung_V:
        round(voltage, 1),

    Strom_A:
        round(current, 2),

    Leistung_W:
        round(power, 0),

    Betrieb:
        operation,


    Kapazitaet_kWh:
        round(capacity, 2),

    Energie_aktuell_kWh:
        round(storedEnergy, 2),


    Lifetime_Geladen_kWh:
        round(lifetimeCharged, 0),

    Lifetime_Entladen_kWh:
        round(lifetimeDischarged, 0),


    Max_Laden_W:
        round(maxCharge, 0),

    Max_Entladen_W:
        round(maxDischarge, 0),


    // Rohdaten bleiben erhalten,
    // werden aber NICHT visualisiert.
    raw:
        c
};


// ======================================================
// Node Status
// ======================================================

const socText =
    soc !== null
        ? soc.toFixed(1)
        : "?";

const sohText =
    soh !== null
        ? soh.toFixed(0)
        : "?";

const tMinText =
    tempMin !== null
        ? tempMin.toFixed(1)
        : "?";

const tMaxText =
    tempMax !== null
        ? tempMax.toFixed(1)
        : "?";


node.status({

    fill: "green",

    shape: "dot",

    text:
        `SOC ${socText}% | ` +
        `SOH ${sohText}% | ` +
        `${tMinText}–${tMaxText} °C`
});


return msg;

// ======================================================
// NODE: URL Powerflow
// Baut die Solar-API-Adresse des Verto aus der
// Einstellung VERTO_IP (Doppelklick auf den Node "Verto Plus").
// ======================================================

const ip = String(env.get("VERTO_IP") || "").trim();

if (!ip) {
    node.status({ fill: "red", shape: "ring", text: "IP fehlt (Doppelklick auf Verto Plus)" });
    return null;
}

msg.url = "http://" + ip + "/solar_api/v1/GetPowerFlowRealtimeData.fcgi";
return msg;

// ======================================================
// NODE: URL Prognose
//
// forecast.solar-Abfrage aus:
// - Standort: Strategie-Einstellungen im Dashboard
//   (derselbe Standort wie für den Sonnenaufgang)
// - PV-Anlage: Einstellungen dieses Geräte-Nodes
//   (PV_NEIGUNG, PV_AZIMUT, PV_KWP)
//
// Schutz vor Server-Sperre:
// - Mindestabstand zwischen zwei Abrufen (PROGNOSE_MIN_ABSTAND_MIN),
//   gilt auch über Deploys hinweg
//
// Ausgänge: 1) Anfrage  2) Status-Text
// ======================================================

const CONFIG_KEY = "$parent.strategy_v7_config";
const LAST_KEY = "forecast_last_request_ts";   // global, übersteht Deploys
const RETRY_MS = 5000;
const MAX_TRIES = 12;

const minGapMin = Number(env.get("PROGNOSE_MIN_ABSTAND_MIN"));
const MIN_GAP_MS = (Number.isFinite(minGapMin) ? Math.max(0, minGapMin) : 30) * 60000;

function status(fill, text) {
    node.status({ fill, shape: fill === "green" ? "dot" : "ring", text });
    node.send([null, { topic: "status", payload: { fill, shape: fill === "green" ? "dot" : "ring", text } }]);
}

function buildUrl() {
    const cfg = flow.get(CONFIG_KEY);
    const lat = Number(cfg?.location?.latitude);
    const lon = Number(cfg?.location?.longitude);

    const tilt = Number(env.get("PV_NEIGUNG"));
    const azimuth = Number(env.get("PV_AZIMUT"));
    const kwp = Number(env.get("PV_KWP"));

    if (![tilt, azimuth, kwp].every(Number.isFinite)) {
        return { error: "PV-Neigung / Azimut / kWp fehlen (Doppelklick auf PV-Prognose)" };
    }

    if (!Number.isFinite(lat) || !Number.isFinite(lon)) {
        return { wait: true };
    }

    return {
        url:
            "https://api.forecast.solar/estimate/" +
            lat.toFixed(4) + "/" +
            lon.toFixed(4) + "/" +
            tilt + "/" +
            azimuth + "/" +
            kwp
    };
}

function request(r) {
    const last = Number(global.get(LAST_KEY)) || 0;
    const age = Date.now() - last;

    if (age < MIN_GAP_MS) {
        status("yellow", "Abruf übersprungen, letzter vor " + Math.round(age / 60000) + " min");
        return;
    }

    global.set(LAST_KEY, Date.now());
    msg.url = r.url;
    node.send([msg, null]);
    status("blue", "Prognose wird abgerufen …");
}

const first = buildUrl();

if (first.error) {
    status("red", first.error);
    return null;
}

if (first.url) {
    request(first);
    return null;
}

// Strategie-Config noch nicht geladen -> warten
let tries = 0;
status("yellow", "warte auf Standort aus Strategie-Einstellungen");

const timer = setInterval(() => {
    tries++;
    const r = buildUrl();

    if (r.url) {
        clearInterval(timer);
        request(r);
    } else if (tries >= MAX_TRIES) {
        clearInterval(timer);
        status("red", "kein Standort in den Strategie-Einstellungen");
    }
}, RETRY_MS);

return null;

// ======================================================
// NODE: URL Shelly Heubelüftung
// Status des Planer-Skripts am Shelly.
// IP aus der Einstellung SHELLY_IP (Node "Heubelüftung").
// ======================================================

const ip = String(env.get("SHELLY_IP") || "").trim();

if (!ip) {
    node.status({ fill: "red", shape: "ring", text: "IP fehlt (Doppelklick auf Heubelüftung)" });
    return null;
}

msg.url = "http://" + ip + "/script/1/planer?status=1";
return msg;

// ======================================================
// NODE: Rückfall-Timer setzen
//
// Schreibt InOutWRte_RvrtTms (SunSpec Storage, Adresse 40378,
// gleiche Zählweise wie StorCtl_Mod 40368 / OutWRte 40375 /
// InWRte 40376).
//
// Wirkung: Werden OutWRte/InWRte so lange nicht neu
// geschrieben (Node-RED steht, Pi hängt), fällt der Verto
// selbst auf die Standardwerte zurück. Im Normalbetrieb
// frischt "Modbus-Befehle bauen" alle 60 s auf.
//
// Einstellung: VERTO_REVERT_S (0 = aus)
// Ausgänge: 1) Modbus-Write  2) Kontroll-Lesen
// ======================================================

const REG_RVRTTMS = 40378;
const UNIT_ID = 1;

const s = Number(env.get("VERTO_REVERT_S"));
const value = Number.isFinite(s) ? Math.max(0, Math.min(28800, Math.round(s))) : 300;

flow.set("rvrt_soll", value);

node.status({
    fill: "blue",
    shape: "dot",
    text: value > 0 ? "Rückfall-Timer " + value + " s geschrieben" : "Rückfall-Timer aus (0)"
});

// Nach dem Schreiben zur Kontrolle zurücklesen
setTimeout(() => {
    node.send([null, {
        topic: "read_rvrttms",
        payload: { fc: 3, unitid: UNIT_ID, address: REG_RVRTTMS, quantity: 1 }
    }]);
}, 3000);

return [{
    topic: "write_rvrttms",
    payload: { value: [value], fc: 6, unitid: UNIT_ID, address: REG_RVRTTMS, quantity: 1 }
}, null];

// ======================================================
// NODE: Rückfall-Timer prüfen
// Vergleicht den zurückgelesenen Wert mit der Einstellung.
// ======================================================

function extract(m) {
    const p = m.payload;
    if (Array.isArray(p?.data)) return p.data[0];
    if (Array.isArray(m?.responseBuffer?.data)) return m.responseBuffer.data[0];
    if (Array.isArray(p)) return p[0];
    if (Array.isArray(p?.buffer)) return p.buffer[0];
    return p;
}

const ist = Number(extract(msg));
const soll = Number(flow.get("rvrt_soll"));
const ok = Number.isFinite(ist) && ist === soll;

flow.set("$parent.verto_revert_s", Number.isFinite(ist) ? ist : null);
flow.set("rvrt_ok", ok);

node.status(ok
    ? { fill: "green", shape: "dot", text: "Rückfall-Timer " + ist + " s bestätigt" }
    : { fill: "yellow", shape: "ring", text: "gelesen " + ist + ", erwartet " + soll });

return null;

// ======================================================
// NODE: Status Verto Plus
// Zusammenfassung am Geräte-Node:
//   SOC | Modbus-Modus | Rückfall-Timer
// Fehler (Catch) werden 60 s lang rot angezeigt.
// ======================================================

const now = Date.now();

if (msg.error) {
    context.set("lastError", {
        text: String(msg.error.message || msg.error).slice(0, 60),
        source: msg.error.source?.name || msg.error.source?.type || "",
        ts: now
    });
}

const err = context.get("lastError");

if (err && now - err.ts < 60000) {
    msg.payload = {
        fill: "red",
        shape: "ring",
        text: (err.source ? err.source + ": " : "") + err.text
    };
    return msg;
}

const soc = Number(flow.get("$parent.soc_percent"));
const mode = flow.get("$parent.readback.storctl_mod");
const revertOk = flow.get("rvrt_ok");
const revert = flow.get("$parent.verto_revert_s");

const MODES = { 0: "Fronius frei", 1: "Ladelimit", 2: "Entladelimit", 3: "Lade+Entladelimit" };

const parts = [
    "SOC " + (Number.isFinite(soc) ? soc.toFixed(0) + " %" : "—"),
    "Modbus: " + (MODES[mode] ?? "—")
];

if (revertOk === true) parts.push("Rückfall " + revert + " s");
else if (revertOk === false) parts.push("Rückfall ?");

msg.payload = { fill: "green", shape: "dot", text: parts.join(" | ") };
return msg;

// ======================================================
// NODE: Status PV-Prognose
// Zeigt am Geräte-Node: Heute / Morgen in kWh,
// Hinweise vom URL-Node oder Fehler (Catch).
// ======================================================

if (msg.topic === "status") {
    return msg;
}

if (msg.error) {
    msg.payload = { fill: "red", shape: "ring", text: "Fehler: " + String(msg.error.message || msg.error).slice(0, 60) };
    return msg;
}

const today = Number(flow.get("$parent.forecast_today_kwh"));
const tomorrow = Number(flow.get("$parent.forecast_tomorrow_kwh"));
const fmt = v => (Number.isFinite(v) ? v.toFixed(1) : "—");

msg.payload = {
    fill: "green",
    shape: "dot",
    text: "Heute " + fmt(today) + " kWh | Morgen " + fmt(tomorrow) + " kWh"
};
return msg;

// ======================================================
// NODE: Status Heubelüftung
// Zeigt am Geräte-Node, ob die Heubelüftung das
// Entladen sperrt, oder ob der Shelly nicht erreichbar ist.
// ======================================================

if (msg.error) {
    msg.payload = { fill: "red", shape: "ring", text: "Shelly nicht erreichbar / Fehler" };
    return msg;
}

const locked = msg.entladen_sperren === true;

msg.payload = locked
    ? { fill: "red", shape: "dot", text: "Heubelüftung aktiv → Entladen gesperrt" }
    : { fill: "green", shape: "dot", text: "Heubelüftung aus → Entladen frei" };

return msg;
